<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>숫자 맞추기</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #e0f2fe; color: #1f2937; padding: 24px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    input { font-size: 18px; padding: 8px; margin: 4px; }
  </style>
</head>
<body>
  <h1>숫자 맞추기</h1>
  <p id="hint">1부터 100 사이의 숫자를 맞혀 보세요</p>
  <input id="guess" type="number">
  <button id="check">확인</button>
  <p id="result"></p>
  <p id="tries">시도: 0번</p>
  <script>
    const answer = Math.floor(Math.random() * (100 - 1 + 1)) + 1;
    let tries = 0;
    const guess = document.getElementById('guess');
    const result = document.getElementById('result');
    document.getElementById('check').addEventListener('click', function () {
      const n = Number(guess.value);
      tries += 1;
      document.getElementById('tries').textContent = '시도: ' + tries + '번';
      if (n === answer) {
        result.textContent = '🎉 정답이에요!';
      } else if (n < answer) {
        result.textContent = '더 큰 수예요 ⬆️';
      } else {
        result.textContent = '더 작은 수예요 ⬇️';
      }
    });
  </script>
</body>
</html>
```

