<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>식물 키우기</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #dcfce7; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
  </style>
</head>
<body>
  <h2 id="title">식물 키우기</h2>
  <h1 id="plant">🌱</h1>
  <p id="stage">🌱 새싹</p>
  <button id="water">물 주기 💧</button>
  <p id="count">물 준 횟수: 0</p>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __size(name, prop, v) {
      var s = $(name).style;
      if (prop === 'opacity') s.opacity = v / 100;
      else if (prop === 'rotate') s.transform = 'rotate(' + v + 'deg)';
      else s[prop] = v + 'px';
    }

    var w;

    document.getElementById("water").addEventListener('click', function () {
      w = (typeof w === 'number' ? w : 0) + 1;
      document.getElementById("count").textContent = '물 준 횟수: ' + String(w);
      __size("plant", "fontSize", 30 + w * 8);
      if (w >= 10) {
        document.getElementById("stage").textContent = '🌳 나무가 됐어요!';
      } else if (w >= 5) {
        document.getElementById("stage").textContent = '🌿 쑥쑥';
      }
    });

    w = 0;
  </script>
</body>
</html>
