    input { font: inherit; padding: 9px 12px; margin: 4px; border: 1px solid #9ca3af; border-radius: 9px; }
  </style>
</head>
<body>
  <h1 id="t">📊 평균 계산기</h1>
  <input id="kor" type="number" placeholder="국어 점수">
  <input id="math" type="number" placeholder="수학 점수">
  <button id="calc">계산</button>
  <h2 id="out"></h2>
  <script>
    var a;

    document.getElementById("calc").addEventListener('click', function () {
      if (Math.min(Math.max((parseFloat(document.getElementById("kor").value) || 0), 0), 100) != (parseFloat(document.getElementById("kor").value) || 0) || Math.min(Math.max((parseFloat(document.getElementById("math").value) || 0), 0), 100) != (parseFloat(document.getElementById("math").value) || 0)) {
        alert('점수를 다시 확인하세요');
      } else {
        a = ((parseFloat(document.getElementById("kor").value) || 0) + (parseFloat(document.getElementById("math").value) || 0)) / 2;
        document.getElementById("out").textContent = ['평균: ',a,'점'].join('');
        if (a < 60) {
          document.getElementById("out").style.color = "#ef4444";
        } else {
          document.getElementById("out").style.color = "#111111";
        }
        document.getElementById("kor").value = '';
        document.getElementById("math").value = '';
      }
    });
  </script>
</body>
