  <input id="secBox" type="number" placeholder="Secondes">
  <button id="startBtn">Démarrer</button>
  <h1 id="left"></h1>
  <script>
    var __timers = [];

    var n, on;

    document.getElementById("startBtn").addEventListener('click', function () {
      n = (parseFloat(document.getElementById("secBox").value) || 0);
      on = true;
      document.getElementById("left").textContent = n;
    });
    __timers.push(setInterval(function () {
      if (on) {
        n = (typeof n === 'number' ? n : 0) + -1;
