  </style>
</head>
<body>
  <h1 id="name">안녕하세요! 저는 민서예요 👋</h1>
  <p id="intro">5학년 2반, 좋아하는 건 그림 그리기와 고양이</p>
  <h3 id="likesTitle">❤️</h3>
  <ul id="likes"></ul>
  <button id="mode">다크 모드</button>
  <a id="blog" href="https://example.com" target="_blank">내 블로그</a>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var dark;

    document.getElementById("mode").addEventListener('click', function () {
      dark = !dark;
      if (dark) {
        document.getElementById("name").style.background = "#111111";
        document.getElementById("name").style.color = "#ffffff";
        document.getElementById("intro").style.color = "#9ca3af";
      } else {
        document.getElementById("name").style.background = "#ffffff";
        document.getElementById("name").style.color = "#111111";
        document.getElementById("intro").style.color = "#111111";
      }
    });

    __add("likes", '🎨 그림');
    __add("likes", '🐱 고양이');
    __add("likes", '🍓 딸기');
    dark = false;
  </script>
</body>
</html>

