  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }

    var secret, tries;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("guessBtn").addEventListener('click', function () {
      tries = (typeof tries === 'number' ? tries : 0) + -1;
      document.getElementById("left").textContent = 'Tries left: ' + String(tries);
      if ((parseFloat(document.getElementById("guessBox").value) || 0) == secret) {
        document.getElementById("msg").textContent = 'Correct! 🎉';
        __show("row1", "hide");
      } else if (tries <= 0) {
        document.getElementById("msg").textContent = 'Game over, it was ' + String(secret);
        __show("row1", "hide");
      } else if ((parseFloat(document.getElementById("guessBox").value) || 0) > secret) {
        document.getElementById("msg").textContent = 'Too high';
      } else {
        document.getElementById("msg").textContent = 'Too low';
      }
    });

    secret = mathRandomInt(1, 20);
    tries = 5;
  </script>
</body>
