    var nums;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function makeNums() {
      nums = [];
      for (var count = 0; count < 10; count++) {
        nums.push(mathRandomInt(1, 100));
      }
      document.getElementById("raw").textContent = '뽑은 숫자: ' + String(nums);
      document.getElementById("sorted").textContent = '';
    }

    function listsGetSortCompare(type, direction) {
      var compareFuncs = {
        'NUMERIC': function(a, b) {
            return Number(a) - Number(b); },
        'TEXT': function(a, b) {
            return String(a) > String(b) ? 1 : -1; },
        'IGNORE_CASE': function(a, b) {
            return String(a).toLowerCase() > String(b).toLowerCase() ? 1 : -1; },
      };
      var compare = compareFuncs[type];
      return function(a, b) { return compare(a, b) * direction; };
    }

    document.getElementById("newBtn").addEventListener('click', function () {
      makeNums();
    });
    document.getElementById("upBtn").addEventListener('click', function () {
      document.getElementById("sorted").textContent = String(nums.slice().sort(listsGetSortCompare("NUMERIC", 1)));
    });
    document.getElementById("downBtn").addEventListener('click', function () {
      document.getElementById("sorted").textContent = String(nums.slice().sort(listsGetSortCompare("NUMERIC", -1)));
    });

    makeNums();
  </script>
</body>
