<body>
  <h1 id="제목1">숫자 맞히기</h1>
  <p id="안내">1부터 100 사이의 숫자를 맞혀 보세요</p>
  <div id="상자1" class="box row">
    <input id="숫자칸" type="number" placeholder="숫자">
    <button id="확인">확인</button>
  </div>
  <h2 id="결과"></h2>
  <script>
    var 정답, 시도, 추측;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("확인").addEventListener('click', function () {
      시도 = (typeof 시도 === 'number' ? 시도 : 0) + 1;
