      if (e.key === "ArrowUp") {
        e.preventDefault();
        __nudge("로켓", 0, -18);
        __stay("로켓");
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowDown") {
        e.preventDefault();
        __nudge("로켓", 0, 18);
        __stay("로켓");
      }
    });

    score = 0;
    __move("로켓", 40, 300);
    __move("별", 200, 200);
  </script>
