<body>
  <h1 id="title1">Tip calculator</h1>
  <input id="billBox" type="number" placeholder="Bill amount">
  <div id="btns" class="box row">
    <button id="b10">10%</button>
    <button id="b15">15%</button>
    <button id="b20">20%</button>
  </div>
  <h3 id="tipText">Tip: 0</h3>
  <h2 id="totalText">Total: 0</h2>
  <script>
    var rate, tip;

    // 이 함수를 설명하세요...
    function calc(rate) {
      tip = Math.round((parseFloat(document.getElementById("billBox").value) || 0) * rate * 100) / 100;
      document.getElementById("tipText").textContent = 'Tip: ' + String(tip);
      document.getElementById("totalText").textContent = 'Total: ' + String(Math.round(((parseFloat(document.getElementById("billBox").value) || 0) + tip) * 100) / 100);
    }

    document.getElementById("b10").addEventListener('click', function () {
      calc(0.1);
    });
    document.getElementById("b15").addEventListener('click', function () {
      calc(0.15);
