<body>
  <h2 id="title">단어 카드</h2>
  <div id="card" class="box" style="background:#ffffff">
    <h1 id="front">achieve</h1>
    <h3 id="back">이루다</h3>
  </div>
  <div id="btns" class="box row">
    <button id="flip">뜻 보기</button>
    <button id="next">다음</button>
    <button id="know">외웠어요 ✅</button>
  </div>
  <p id="count">외운 단어: 0</p>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }

    var w, i, got, m;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("flip").addEventListener('click', function () {
      __show("back", "toggle");
    });
    document.getElementById("next").addEventListener('click', function () {
      i = mathRandomInt(1, w.length);
      document.getElementById("front").textContent = w[(i - 1)];
      document.getElementById("back").textContent = m[(i - 1)];
      __show("back", "hide");
    });
    document.getElementById("know").addEventListener('click', function () {
      got = (typeof got === 'number' ? got : 0) + 1;
      document.getElementById("count").textContent = '외운 단어: ' + String(got);
      i = mathRandomInt(1, w.length);
      document.getElementById("front").textContent = w[(i - 1)];
      document.getElementById("back").textContent = m[(i - 1)];
      __show("back", "hide");
    });

    w = ['achieve', 'borrow', 'careful', 'decide', 'enough'];
    m = ['이루다', '빌리다', '조심하는', '결정하다', '충분한'];
    i = 1;
    got = 0;
    __show("back", "hide");
  </script>
</body>
