    <button id="h2">🕳️</button>
  </div>
  <div id="r2" class="box row">
    <button id="h3">🕳️</button>
    <button id="h4">🕳️</button>
  </div>
  <div id="info" class="box row">
    <p id="score">Score: 0</p>
    <p id="time">Time: 30</p>
  </div>
  <button id="go">Start</button>
  <script>
    var __timers = [];
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var k, playing, score, mole, left;

    // 이 함수를 설명하세요...
    function hit(k) {
      if (playing && k == mole) {
        score = (typeof score === 'number' ? score : 0) + 1;
        document.getElementById("score").textContent = 'Score: ' + String(score);
        mole = 0;
        __beep(523.25, 0.1);
      }
    }

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("go").addEventListener('click', function () {
      score = 0;
      left = 30;
      playing = true;
      document.getElementById("score").textContent = 'Score: ' + String(0);
    });
    __timers.push(setInterval(function () {
      if (playing) {
        document.getElementById("h1").textContent = '🕳️';
        document.getElementById("h2").textContent = '🕳️';
        document.getElementById("h3").textContent = '🕳️';
        document.getElementById("h4").textContent = '🕳️';
        mole = mathRandomInt(1, 4);
        if (mole == 1) {
          document.getElementById("h1").textContent = '🐹';
        }
        if (mole == 2) {
          document.getElementById("h2").textContent = '🐹';
        }
        if (mole == 3) {
          document.getElementById("h3").textContent = '🐹';
        }
        if (mole == 4) {
          document.getElementById("h4").textContent = '🐹';
        }
      }
    }, 1000));
    __timers.push(setInterval(function () {
      if (playing) {
        left = (typeof left === 'number' ? left : 0) + -1;
        document.getElementById("time").textContent = 'Time: ' + String(left);
        if (left <= 0) {
          playing = false;
          mole = 0;
          document.getElementById("time").textContent = 'Done! Score: ' + String(score);
        }
      }
    }, 1000));
    document.getElementById("h1").addEventListener('click', function () {
      hit(1);
    });
    document.getElementById("h2").addEventListener('click', function () {
      hit(2);
    });
    document.getElementById("h3").addEventListener('click', function () {
      hit(3);
    });
    document.getElementById("h4").addEventListener('click', function () {
      hit(4);
    });

    playing = false;
    mole = 0;
  </script>
