      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }

    var choice, Q, score, A, i, base, R;

    // 이 함수를 설명하세요...
    function showQ() {
      if (i > 3) {
        __show("choices", "hide");
        document.getElementById("q").textContent = ['Finished! Final score: ',score,' / 3'].join('');
