        document.getElementById("q").textContent = Q[(i - 1)];
        base = (i - 1) * 3;
        document.getElementById("c1").textContent = A[((base + 1) - 1)];
        document.getElementById("c2").textContent = A[((base + 2) - 1)];
        document.getElementById("c3").textContent = A[((base + 3) - 1)];
      }
    }

    // 이 함수를 설명하세요...
    function pick(choice) {
      if (choice == R[(i - 1)]) {
        score = (typeof score === 'number' ? score : 0) + 1;
        document.getElementById("msg").textContent = 'Correct! 🎉';
      } else {
        document.getElementById("msg").textContent = 'Oops 😢 Answer: ' + String(R[(i - 1)]);
