<body>
  <h2 id="t">🦖 점프!</h2>
  <canvas id="cv" width="300" height="150"></canvas>
  <h3 id="sc">점수 0</h3>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    var __timers = [];
    function __pen(name) { return $(name).getContext('2d'); }
    function __clear(name) { var c = $(name); __pen(name).clearRect(0, 0, c.width, c.height); }
    function __rect(name, x, y, w, h, color) { var g = __pen(name); g.fillStyle = color; g.fillRect(x, y, w, h); }

    var height, speed, ox, score;

    document.addEventListener('keydown', function (e) {
      if (e.key === " ") {
        e.preventDefault();
        if (height == 0) {
          speed = 12;
        }
      }
    });
    __timers.push(setInterval(function () {
      height = (typeof height === 'number' ? height : 0) + speed;
      speed = (typeof speed === 'number' ? speed : 0) + -1;
      if (height <= 0) {
        height = 0;
        speed = 0;
      }
      ox = (typeof ox === 'number' ? ox : 0) + -6;
      if (ox < -20) {
        ox = 300;
        score = (typeof score === 'number' ? score : 0) + 1;
        document.getElementById("sc").textContent = '점수 ' + String(score);
      }
      __clear("cv");
      __rect("cv", 20, 120 - height, 30, 30, '#22c55e');
      __rect("cv", ox, 120, 20, 30, '#92400e');
      if (ox < 50 && ox > 10 && height < 20) {
        __timers.forEach(clearInterval);
        document.getElementById("sc").textContent = '게임 오버! 점수 ' + String(score);
      }
    }, 30));

    height = 0;
    speed = 0;
    ox = 300;
    score = 0;
  </script>
</body>
