      for (i = 1; i_inc >= 0 ? i <= i_end : i >= i_end; i += i_inc) {
        __circle("cv", xs[(i - 1)], (i * 29 + t * (1 + i % 3)) % 240, 3, "#ffffff");
      }
    }, 50));

    document.getElementById("cv").style.background = "#111111";
    t = 0;
    xs = [];
    for (i = 1; i <= 40; i++) {
      xs.push(mathRandomInt(0, 320));
    }
