  <h2 id="last">첫 단어: 기차</h2>
  <div id="r" class="box row">
    <input id="w" type="text" placeholder="다음 단어">
    <button id="go">이어가기</button>
  </div>
  <p id="msg"></p>
  <ul id="hist"></ul>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var prev, word;

    document.getElementById("go").addEventListener('click', function () {
      word = document.getElementById("w").value.trim();
      if (word.length < 2) {
        document.getElementById("msg").textContent = '두 글자 이상 써 줘!';
      } else if (word.charAt(0) != prev.slice(-1)) {
        document.getElementById("msg").textContent = '앞 단어 끝 글자로 시작해야 해요 ❌';
      } else {
        __add("hist", word);
        prev = word;
        document.getElementById("last").textContent = '지금 단어: ' + String(word);
        document.getElementById("msg").textContent = '좋아요 ⭕';
        __beep(329.63, 0.1);
      }
      document.getElementById("w").value = '';
    });

    prev = '기차';
  </script>
</body>
