  <title>Checkerboard</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #ffffff; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
    input { font: inherit; padding: 9px 12px; margin: 4px; border: 1px solid #9ca3af; border-radius: 9px; }
    canvas { max-width: 100%; background: #ffffff; border: 1px solid #d1d5db; border-radius: 8px; touch-action: manipulation; }
  </style>
</head>
<body>
  <h2 id="title">Checkerboard</h2>
  <input id="n" type="number" placeholder="Size (2-10)">
  <button id="draw">Draw</button>
  <canvas id="cv" width="240" height="240"></canvas>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __pen(name) { return $(name).getContext('2d'); }
    function __clear(name) { var c = $(name); __pen(name).clearRect(0, 0, c.width, c.height); }
    function __rect(name, x, y, w, h, color) { var g = __pen(name); g.fillStyle = color; g.fillRect(x, y, w, h); }

    var k, s, r, c;

    document.getElementById("draw").addEventListener('click', function () {
      __clear("cv");
      k = Math.min(Math.max((parseFloat(document.getElementById("n").value) || 0), 2), 10);
      s = 240 / k;
      var r_end = k - 1;
      var r_inc = 1;
      if (0 > r_end) {
        r_inc = -r_inc;
      }
      for (r = 0; r_inc >= 0 ? r <= r_end : r >= r_end; r += r_inc) {
        var c_end = k - 1;
        var c_inc = 1;
        if (0 > c_end) {
          c_inc = -c_inc;
        }
        for (c = 0; c_inc >= 0 ? c <= c_end : c >= c_end; c += c_inc) {
          if ((r + c) % 2 === 0) {
            __rect("cv", c * s, r * s, s, s, "#111111");
          }
        }
      }
    });
  </script>
</body>
</html>
