<body>
  <h1 id="title">회원가입</h1>
  <div id="form" class="box">
    <input id="nameBox" type="text" placeholder="이름">
    <input id="ageBox" type="number" placeholder="나이">
    <input id="pwBox" type="text" placeholder="비밀번호">
    <input id="pw2Box" type="text" placeholder="비밀번호 확인">
    <button id="submit">가입하기</button>
    <p id="error"></p>
  </div>
  <h2 id="welcome"></h2>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }

    document.getElementById("submit").addEventListener('click', function () {
      if (!document.getElementById("nameBox").value.trim().length) {
        document.getElementById("error").textContent = '이름을 써 주세요';
