    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <div id="light" class="box" style="background:#ef4444">
    <p id="lt">Wait for green!</p>
  </div>
  <div id="btns" class="box row">
    <button id="go">Start</button>
    <button id="hit">Click!</button>
  </div>
  <h2 id="result"></h2>
  <script>
    var __timers = [];

    var wait, on, t;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("go").addEventListener('click', function () {
      wait = true;
      document.getElementById("light").style.background = "#ef4444";
      setTimeout(function () {
        if (wait) {
          wait = false;
          on = true;
          t = 0;
          document.getElementById("light").style.background = "#22c55e";
        }
      }, (mathRandomInt(2, 5)) * 1000);
    });
    __timers.push(setInterval(function () {
      if (on) {
        t = (typeof t === 'number' ? t : 0) + 1;
      }
    }, 20));
    document.getElementById("hit").addEventListener('click', function () {
      if (wait) {
        wait = false;
        document.getElementById("result").textContent = 'Too soon!';
      } else if (on) {
        on = false;
        document.getElementById("result").textContent = String(t / 100) + ' seconds';
      }
    });

    wait = false;
    on = false;
  </script>
</body>
</html>
