  <button id="rollBtn">주사위 던지기</button>
  <h2 id="result"></h2>
  <script>
    var me, com;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("rollBtn").addEventListener('click', function () {
      me = mathRandomInt(1, 6);
      com = mathRandomInt(1, 6);
      document.getElementById("meTx").textContent = '나: ' + String(me);
      document.getElementById("comTx").textContent = '컴퓨터: ' + String(com);
      if (me > com) {
        document.getElementById("result").textContent = '내가 이겼다! 🎉';
      } else if (me < com) {
        document.getElementById("result").textContent = '컴퓨터 승 🤖';
      } else {
        document.getElementById("result").textContent = '무승부!';
      }
    });
  </script>
</body>
</html>
