  <h2 id="bal">남은 돈: 30000원</h2>
  <input id="amt" type="number" placeholder="금액">
  <button id="inB">받았어요 +</button>
  <button id="outB">썼어요 -</button>
  <ul id="hist"></ul>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var money;

    document.getElementById("inB").addEventListener('click', function () {
      money = (typeof money === 'number' ? money : 0) + (parseFloat(document.getElementById("amt").value) || 0);
      document.getElementById("bal").textContent = ['남은 돈: ',money,'원'].join('');
      __add("hist", '+' + String((parseFloat(document.getElementById("amt").value) || 0)));
    });
    document.getElementById("outB").addEventListener('click', function () {
      if ((parseFloat(document.getElementById("amt").value) || 0) > money) {
        alert('돈이 모자라요!');
      } else {
        money = (typeof money === 'number' ? money : 0) + (0 - (parseFloat(document.getElementById("amt").value) || 0));
        document.getElementById("bal").textContent = ['남은 돈: ',money,'원'].join('');
        __add("hist", '-' + String((parseFloat(document.getElementById("amt").value) || 0)));
      }
    });

    money = 30000;
  </script>
</body>
</html>
