          score = (typeof score === 'number' ? score : 0) + 1;
          document.getElementById("scoreTx").textContent = 'Punkte: ' + String(score);
          document.getElementById("wordTx").textContent = listsGetRandomItem(words, false);
        } else {
          document.getElementById("scoreTx").textContent = 'Tippfehler! Nochmal';
        }
        document.getElementById("typeIn").value = '';
      }
    });

    words = ['Hund', 'Katze', 'Maus', 'Vogel'];
