  <p id="level">Digits: 3</p>
  <h1 id="shown">?</h1>
  <button id="go">Show me</button>
  <input id="guess" type="text" placeholder="Type the number you saw">
  <button id="check">Check</button>
  <p id="msg"></p>
  <script>
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var digits, secret;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("go").addEventListener('click', function () {
      secret = '';
      for (var count = 0; count < digits; count++) {
        secret = String(secret) + String(mathRandomInt(0, 9));
      }
      document.getElementById("shown").textContent = secret;
      document.getElementById("guess").value = '';
      document.getElementById("msg").textContent = '';
      setTimeout(function () {
        document.getElementById("shown").textContent = '???';
      }, (2) * 1000);
    });
    document.getElementById("check").addEventListener('click', function () {
      if (!secret.length) {
      } else if (document.getElementById("guess").value.trim() == secret) {
        digits = (typeof digits === 'number' ? digits : 0) + 1;
        document.getElementById("msg").textContent = 'Correct! One more digit';
        __beep(523.25, 0.2);
      } else {
        document.getElementById("msg").textContent = 'Wrong. It was ' + String(secret);
        digits = 3;
      }
      secret = '';
      document.getElementById("level").textContent = 'Digits: ' + String(digits);
    });

    digits = 3;
    secret = '';
  </script>
</body>
