  <button id="submit">제출</button>
  <p id="result"></p>
  <p id="score">점수: 0</p>
  <script>
    const quiz = [["6 × 7 = ?","42"],["8 × 9 = ?","72"],["4 × 12 = ?","48"]];
    let index = 0;
    let score = 0;
