  <h2 id="out"></h2>
  <script>
    var num, d, x;

    // 이 함수를 설명하세요...
    function smallest(num) {
      var d_inc = 1;
      if (2 > num) {
        d_inc = -d_inc;
      }
      for (d = 2; d_inc >= 0 ? d <= num : d >= num; d += d_inc) {
        if (num % d == 0) {
          return d;
        }
      }
      return num;
    }

    document.getElementById("go").addEventListener('click', function () {
      x = (parseFloat(document.getElementById("n").value) || 0);
      if (x < 2 || !(x % 1 === 0)) {
        document.getElementById("out").textContent = 'Enter a whole number 2 or bigger';
      } else if (smallest(x) == x) {
        document.getElementById("out").textContent = String(x) + ' is prime ✅';
      } else {
        document.getElementById("out").textContent = [x,' is not prime ❌ (divisible by ',smallest(x),')'].join('');
      }
    });
  </script>
