  </style>
</head>
<body>
  <h2 id="title">버튼 잡기</h2>
  <div id="info" class="box row">
    <h3 id="sc">점수: 0</h3>
    <h3 id="tm">남은 시간: 15</h3>
  </div>
  <p id="hint">버튼을 최대한 많이 누르세요</p>
  <button id="tgt">🎯 눌러!</button>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __move(name, x, y) {
      var s = $(name).style;
      s.position = 'absolute';
      s.left = x + 'px';
      s.top = y + 'px';
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }
    var __timers = [];

    var score, t;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("tgt").addEventListener('click', function () {
      score = (typeof score === 'number' ? score : 0) + 1;
      document.getElementById("sc").textContent = '점수: ' + String(score);
      __move("tgt", mathRandomInt(10, 250), mathRandomInt(150, 350));
    });
    __timers.push(setInterval(function () {
      t = (typeof t === 'number' ? t : 0) + -1;
      document.getElementById("tm").textContent = '남은 시간: ' + String(t);
      if (t <= 0) {
        __timers.forEach(clearInterval);
        __show("tgt", "hide");
        document.getElementById("hint").textContent = '시간 끝!';
      }
    }, 1000));

    score = 0;
    t = 15;
    __move("tgt", 130, 200);
  </script>
</body>
</html>
