<body>
  <h1 id="title1">업다운 1~100</h1>
  <input id="guessBox" type="number" placeholder="숫자">
  <button id="checkBtn">확인</button>
  <h2 id="out"></h2>
  <p id="left">남은 기회: 7</p>
  <script>
    var answer, tries;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("checkBtn").addEventListener('click', function () {
      tries = (typeof tries === 'number' ? tries : 0) + 1;
      if ((parseFloat(document.getElementById("guessBox").value) || 0) == answer) {
        document.getElementById("out").textContent = '정답! 🎉';
      } else if (tries >= 7) {
        document.getElementById("out").textContent = '기회 끝! 정답은 ' + String(answer);
      } else if ((parseFloat(document.getElementById("guessBox").value) || 0) < answer) {
        document.getElementById("out").textContent = '업 ⬆';
      } else {
        document.getElementById("out").textContent = '다운 ⬇';
      }
      document.getElementById("left").textContent = '남은 기회: ' + String(7 - tries);
    });

    answer = mathRandomInt(1, 100);
    tries = 0;
  </script>
</body>
