  <script>
    var __timers = [];

    var words, w, left, score;

    function listsGetRandomItem(list, remove) {
      var x = Math.floor(Math.random() * list.length);
      if (remove) {
        return list.splice(x, 1)[0];
      } else {
        return list[x];
      }
    }

    // 이 함수를 설명하세요...
    function next() {
      w = listsGetRandomItem(words, false);
      document.getElementById("word").textContent = w;
    }

    document.addEventListener('keydown', function (e) {
      if (e.key === "Enter") {
        e.preventDefault();
        if (left > 0) {
          if (document.getElementById("typed").value == w) {
            score = (typeof score === 'number' ? score : 0) + 1;
            document.getElementById("msg").textContent = '맞았어요! ⭕';
            next();
          } else {
            document.getElementById("msg").textContent = '틀렸어요 ❌';
          }
          document.getElementById("typed").value = '';
        }
      }
    });
    __timers.push(setInterval(function () {
      left = (typeof left === 'number' ? left : 0) + -1;
      if (left == 0) {
        __timers.forEach(clearInterval);
        document.getElementById("msg").textContent = ['30초 끝! 점수는 ',score,'점'].join('');
      }
    }, 1000));

    words = ['사과', '학교', '친구', '컴퓨터', '무지개'];
    score = 0;
    left = 30;
