    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h2 id="title">구구단 스피드</h2>
  <h1 id="problem">?</h1>
  <input id="ans" type="number" placeholder="답 쓰고 Enter">
  <div id="info" class="box row">
    <p id="score">맞힌 개수: 0</p>
    <p id="time">남은 시간: 45</p>
  </div>
  <button id="go">시작</button>
  <p id="best">최고 기록: 0</p>
  <script>
    var __timers = [];
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var a, playing, score, b, hi, left;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function newProblem() {
      a = mathRandomInt(1, 20);
      b = mathRandomInt(1, 20);
      document.getElementById("problem").textContent = [a,' - ',b,' = ?'].join('');
      document.getElementById("ans").value = '';
    }

    document.getElementById("go").addEventListener('click', function () {
      score = 0;
      left = 45;
      playing = true;
      document.getElementById("score").textContent = '맞힌 개수: ' + String(0);
      newProblem();
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "Enter") {
        e.preventDefault();
        if (playing) {
          if ((parseFloat(document.getElementById("ans").value) || 0) == a - b) {
            score = (typeof score === 'number' ? score : 0) + 1;
            document.getElementById("score").textContent = '맞힌 개수: ' + String(score);
            __beep(329.63, 0.08);
          }
          newProblem();
        }
      }
    });
    __timers.push(setInterval(function () {
      if (playing) {
        left = (typeof left === 'number' ? left : 0) + -1;
        document.getElementById("time").textContent = '남은 시간: ' + String(left);
        if (left <= 0) {
          playing = false;
          document.getElementById("problem").textContent = '끝! 맞힌 개수: ' + String(score);
          if (score > hi) {
            hi = score;
            document.getElementById("best").textContent = '최고 기록: ' + String(hi);
          }
        }
      }
    }, 1000));

    playing = false;
    hi = 0;
  </script>
</body>
</html>
