  <p id="점수판">점수: 0 / 5</p>
  <h1 id="별">⭐</h1>
  <h1 id="로켓">🚀</h1>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __move(name, x, y) {
      var s = $(name).style;
      s.position = 'absolute';
      s.left = x + 'px';
      s.top = y + 'px';
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }
    function __nudge(name, dx, dy) {
      var el = $(name), s = el.style;
      if (s.position !== 'absolute') {
        var r = el.getBoundingClientRect();
        s.position = 'absolute';
        s.left = (r.left + window.pageXOffset) + 'px';
        s.top = (r.top + window.pageYOffset) + 'px';
      }
      s.left = ((parseFloat(s.left) || 0) + dx) + 'px';
      s.top = ((parseFloat(s.top) || 0) + dy) + 'px';
    }
    function __hit(a, b) {
      var p = $(a).getBoundingClientRect(), q = $(b).getBoundingClientRect();
      return p.left < q.right && p.right > q.left && p.top < q.bottom && p.bottom > q.top;
    }
    function __stay(name) {
      var el = $(name), s = el.style, d = document.documentElement;
      if (s.position !== 'absolute') return;
      var x = Math.max(0, Math.min(parseFloat(s.left) || 0, d.clientWidth - el.offsetWidth));
      var y = Math.max(0, Math.min(parseFloat(s.top) || 0, d.clientHeight - el.offsetHeight));
      s.left = x + 'px';
      s.top = y + 'px';
    }
    var __timers = [];
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

