  <h1 id="title">🎵 Metronome</h1>
  <h1 id="dot">●</h1>
  <div id="r" class="box row">
    <button id="slow">60 BPM</button>
    <button id="fast">120 BPM</button>
    <button id="off">Stop</button>
  </div>
  <script>
    var __timers = [];
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var mode;

    document.getElementById("slow").addEventListener('click', function () {
      mode = 1;
    });
    document.getElementById("fast").addEventListener('click', function () {
      mode = 2;
    });
    document.getElementById("off").addEventListener('click', function () {
      mode = 0;
    });
    __timers.push(setInterval(function () {
      if (mode == 1) {
        __beep(440.00, 0.05);
        document.getElementById("dot").style.color = 'hsl(' + Math.floor(Math.random() * 360) + ', 80%, 60%)';
      }
    }, 1000));
    __timers.push(setInterval(function () {
      if (mode == 2) {
        __beep(523.25, 0.05);
        document.getElementById("dot").style.color = 'hsl(' + Math.floor(Math.random() * 360) + ', 80%, 60%)';
      }
    }, 500));

