      if (!!document.getElementById("task").value.trim().length) {
        __add("list", document.getElementById("task").value.trim());
        all = (typeof all === 'number' ? all : 0) + 1;
        document.getElementById("task").value = '';
        document.getElementById("stat").textContent = ['To do: ',all - done,' · Done: ',done].join('');
