```html
<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>발표자 뽑기</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #fff8e1; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
    ul { display: inline-block; text-align: left; }
  </style>
</head>
<body>
  <h1 id="title1">🎤 발표자 뽑기</h1>
  <h1 id="nameText">?</h1>
  <button id="pickBtn">뽑기</button>
  <ul id="done"></ul>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var names, pick;

    function listsGetRandomItem(list, remove) {
      var x = Math.floor(Math.random() * list.length);
      if (remove) {
        return list.splice(x, 1)[0];
      } else {
        return list[x];
      }
    }

    document.getElementById("pickBtn").addEventListener('click', function () {
      if (names.length == 0) {
        document.getElementById("nameText").textContent = '모두 뽑았어요!';
      } else {
        pick = listsGetRandomItem(names, true);
        document.getElementById("nameText").textContent = pick;
        __add("done", pick);
      }
    });

    names = ['지수', '하준', '서연', '도윤', '민서'];
  </script>
</body>
</html>
