    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h2 id="title">반응 속도 테스트</h2>
  <div id="pad" class="box" style="background:#9ca3af">
    <h1 id="sign">⏸</h1>
  </div>
  <div id="btns" class="box row">
    <button id="go">시작</button>
    <button id="tap">누르기</button>
  </div>
  <p id="msg"></p>
  <p id="bestText">최고 기록: -</p>
  <script>
    var __timers = [];

    var state, t, best;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("go").addEventListener('click', function () {
      state = 1;
      document.getElementById("msg").textContent = '기다려요... 초록색이 되면 누르세요!';
      document.getElementById("pad").style.background = "#ef4444";
      setTimeout(function () {
        if (state == 1) {
          state = 2;
          t = 0;
          document.getElementById("pad").style.background = "#22c55e";
          document.getElementById("sign").textContent = '지금!';
        }
      }, (mathRandomInt(2, 5)) * 1000);
    });
    document.getElementById("tap").addEventListener('click', function () {
      if (state == 1) {
        state = 0;
        document.getElementById("msg").textContent = '너무 빨라요! 다시 시작하세요';
        document.getElementById("pad").style.background = "#9ca3af";
      } else if (state == 2) {
        state = 0;
        document.getElementById("pad").style.background = "#9ca3af";
        document.getElementById("sign").textContent = '⏸';
        document.getElementById("msg").textContent = ['반응 시간: ',t,'초'].join('');
        if (best == 0 || t < best) {
          best = t;
          document.getElementById("bestText").textContent = ['최고 기록: ',best,'초'].join('');
        }
      }
    });
    __timers.push(setInterval(function () {
      if (state == 2) {
        t = Math.round((t + 0.1) * 10) / 10;
      }
    }, 100));

    state = 0;
    t = 0;
    best = 0;
  </script>
</body>
</html>
