    });
    function update() {
      document.getElementById('info').textContent = '점수: ' + score + ' · 남은 시간: ' + left + '초';
    }
    const timer = setInterval(function () {
      left -= 1;
      update();
      if (left <= 0) {
        clearInterval(timer);
        document.getElementById('info').textContent = '끝! 점수: ' + score + '점 🎉';
      }
    }, 1000);
  </script>
</body>
