        document.getElementById("res").textContent = 'Incorrecto ❌';
      }
      i = (typeof i === 'number' ? i : 0) + 1;
      if (i > qs.length) {
        document.getElementById("q").textContent = ['¡Fin del quiz! Puntos: ',score,' / ',qs.length].join('');
        __show("row1", "hide");
      } else {
        ask();
      }
    });

    qs = ['perro', 'gato', 'casa', 'libro'];
    as = ['dog', 'cat', 'house', 'book'];
    i = 1;
    score = 0;
