    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    var __mx = 0, __my = 0;
    function __pos(e, el) {
      var r = el.getBoundingClientRect();
      __mx = Math.round((e.clientX - r.left) * (el.width ? el.width / r.width : 1));
      __my = Math.round((e.clientY - r.top) * (el.height ? el.height / r.height : 1));
    }
    function __pen(name) { return $(name).getContext('2d'); }
    function __line(name, x1, y1, x2, y2, color) { var g = __pen(name); g.strokeStyle = color; g.lineWidth = 3; g.lineCap = 'round'; g.beginPath(); g.moveTo(x1, y1); g.lineTo(x2, y2); g.stroke(); }

    var lx, ly;

    document.getElementById("paper").addEventListener('click', function (e) {
      __pos(e, this);
      if (lx >= 0) {
        __line("paper", lx, ly, __mx, __my, "#111111");
      }
      lx = __mx;
      ly = __my;
    });

