    <button id="rstB">Reset</button>
  </div>
  <script>
    var __timers = [];
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var secs, running, mode;

    // 이 함수를 설명하세요...
    function show() {
      document.getElementById("clock").textContent = [Math.floor(secs / 60),':',secs % 60 < 10 ? '0' + String(secs % 60) : secs % 60].join('');
    }

    document.getElementById("goB").addEventListener('click', function () {
      running = 1;
    });
    document.getElementById("rstB").addEventListener('click', function () {
      running = 0;
      mode = 'work';
      secs = 1500;
      show();
      document.getElementById("state").textContent = 'Focus time';
    });
    __timers.push(setInterval(function () {
      if (running == 1) {
        secs = (typeof secs === 'number' ? secs : 0) + -1;
        show();
        if (secs <= 0) {
          __beep(523.25, 0.5);
          if (mode == 'work') {
            mode = 'break';
            secs = 300;
            document.getElementById("state").textContent = 'Break time - relax!';
          } else {
            running = 0;
            document.getElementById("state").textContent = 'All done! Press Reset for another round';
          }
        }
      }
    }, 1000));

    secs = 1500;
    mode = 'work';
    running = 0;
  </script>
</body>
