  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __move(name, x, y) {
      var s = $(name).style;
      s.position = 'absolute';
      s.left = x + 'px';
      s.top = y + 'px';
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }
    var __timers = [];

    var pts, left;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("target").addEventListener('click', function () {
      if (left > 0) {
        pts = (typeof pts === 'number' ? pts : 0) + 1;
        document.getElementById("score").textContent = 'Score: ' + String(pts);
        __move("target", mathRandomInt(10, 300), mathRandomInt(90, 450));
      }
    });
    __timers.push(setInterval(function () {
      left = (typeof left === 'number' ? left : 0) + -1;
      document.getElementById("time").textContent = 'Time: ' + String(left);
      if (left <= 0) {
        __timers.forEach(clearInterval);
        __show("target", "hide");
        document.getElementById("time").textContent = 'Game over! Final score: ' + String(pts);
      }
    }, 1000));

    pts = 0;
    left = 15;
  </script>
</body>
