    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowRight") {
        e.preventDefault();
        bx = (typeof bx === 'number' ? bx : 0) + 20;
      }
    });
    __timers.push(setInterval(function () {
      __clear("game");
      __rect("game", bx, 280, 60, 14, "#a855f7");
      __circle("game", fx, fy, 10, "#f97316");
      fy = (typeof fy === 'number' ? fy : 0) + 3;
      if (fy > 300) {
        if (Math.abs(fx - (bx + 30)) < 40) {
          pts = (typeof pts === 'number' ? pts : 0) + 1;
          document.getElementById("score").textContent = pts;
        }
        fy = 0;
        fx = mathRandomInt(10, 290);
      }
    }, 30));

