  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }

    var odd, coin, n;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function bet(odd) {
      n = mathRandomInt(1, 10);
      document.getElementById("num").textContent = n;
      if (n % 2 == odd) {
        coin = (typeof coin === 'number' ? coin : 0) + 10;
        document.getElementById("res").textContent = '맞았어요! +10';
      } else {
        coin = (typeof coin === 'number' ? coin : 0) + -5;
        document.getElementById("res").textContent = '틀렸어요 -5';
      }
      document.getElementById("coins").textContent = '🪙 코인: ' + String(coin);
      if (coin <= 0) {
        document.getElementById("res").textContent = '게임 오버! 😵';
        __show("odd", "hide");
        __show("even", "hide");
      }
    }

    document.getElementById("odd").addEventListener('click', function () {
      bet(1);
    });
    document.getElementById("even").addEventListener('click', function () {
      bet(0);
    });

    coin = 50;
  </script>
</body>
