Request: ajoute un bouton « Nouvelle question » qui pose une multiplication au hasard (tables de 2 à 9) et compte les bonnes réponses

```html
<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>Quiz</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #e0f2fe; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
    input { font: inherit; padding: 9px 12px; margin: 4px; border: 1px solid #9ca3af; border-radius: 9px; }
  </style>
</head>
<body>
  <h1 id="question">Combien font 7 × 8 ?</h1>
  <input id="rep" type="number" placeholder="Ta réponse">
  <button id="verif">Vérifier</button>
  <button id="nouv">Nouvelle question</button>
  <h2 id="res"></h2>
  <p id="sc">Bonnes réponses : 0</p>
  <script>
    var a, b, ok;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("verif").addEventListener('click', function () {
      if ((parseFloat(document.getElementById("rep").value) || 0) == a * b) {
        document.getElementById("res").textContent = 'Bravo !';
        ok = (typeof ok === 'number' ? ok : 0) + 1;
        document.getElementById("sc").textContent = 'Bonnes réponses : ' + String(ok);
      } else {
        document.getElementById("res").textContent = 'Non, essaie encore';
      }
    });
    document.getElementById("nouv").addEventListener('click', function () {
      a = mathRandomInt(2, 9);
      b = mathRandomInt(2, 9);
      document.getElementById("question").textContent = ['Combien font ',a,' × ',b,' ?'].join('');
    });

    a = 7;
    b = 8;
    ok = 0;
  </script>
</body>
</html>
