  </style>
</head>
<body>
  <h2 id="title">타이머</h2>
  <h1 id="clock">0:00</h1>
  <div id="inputs" class="box row">
    <input id="minBox" type="number" placeholder="분">
    <input id="secBox" type="number" placeholder="초">
  </div>
  <div id="btns" class="box row">
    <button id="go">시작</button>
    <button id="pause">일시정지</button>
    <button id="reset">초기화</button>
  </div>
  <div id="presetRow" class="box row">
    <button id="p1">1:00</button>
    <button id="p3">3:00</button>
    <button id="p5">5:00</button>
  </div>
  <p id="msg"></p>
  <script>
    var __timers = [];
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var s, left, running;

    // 이 함수를 설명하세요...
    function showTime() {
      s = left % 60;
      document.getElementById("clock").textContent = [Math.floor(left / 60),s < 10 ? ':0' : ':',s].join('');
    }

    document.getElementById("go").addEventListener('click', function () {
      if (left == 0) {
        left = (parseFloat(document.getElementById("minBox").value) || 0) * 60 + (parseFloat(document.getElementById("secBox").value) || 0);
      }
      running = left > 0;
      document.getElementById("msg").textContent = '';
      showTime();
    });
    document.getElementById("pause").addEventListener('click', function () {
      running = false;
    });
    document.getElementById("reset").addEventListener('click', function () {
      running = false;
      left = 0;
      showTime();
      document.getElementById("msg").textContent = '';
    });
    __timers.push(setInterval(function () {
      if (running && left > 0) {
        left = (typeof left === 'number' ? left : 0) + -1;
        showTime();
        document.getElementById("clock").style.color = left <= 10 ? "#ef4444" : "#ffffff";
        if (left == 0) {
          running = false;
          document.getElementById("msg").textContent = '⏰ 시간 끝!';
          __beep(523.25, 0.8);
        }
      }
    }, 1000));
    document.getElementById("p1").addEventListener('click', function () {
      running = false;
      left = 60;
      showTime();
    });
    document.getElementById("p3").addEventListener('click', function () {
      running = false;
      left = 180;
      showTime();
    });
    document.getElementById("p5").addEventListener('click', function () {
      running = false;
      left = 300;
      showTime();
    });

    left = 0;
    running = false;
  </script>
</body>
</html>
