      if (!text) return;
      const li = document.createElement('li');
      li.textContent = text + ' ';
      const del = document.createElement('button');
      del.textContent = '삭제';
      del.addEventListener('click', function () {
        li.remove();
        update();
      });
      li.appendChild(del);
      list.appendChild(li);
      item.value = '';
      update();
    });
    update();
  </script>
</body>
</html>
