    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h2 id="title">성적표</h2>
  <div id="in" class="box row">
    <input id="nm" type="text" placeholder="이름">
    <input id="sc" type="number" placeholder="점수">
    <button id="addBtn">추가</button>
  </div>
  <ul id="rows"></ul>
  <p id="avg">평균: -</p>
  <p id="top">최고: -</p>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var scores, best, sum, bestName, s;

    document.getElementById("addBtn").addEventListener('click', function () {
      if (!!document.getElementById("nm").value.trim().length && !!document.getElementById("sc").value.length) {
        scores.push((parseFloat(document.getElementById("sc").value) || 0));
        __add("rows", [document.getElementById("nm").value.trim(),': ',(parseFloat(document.getElementById("sc").value) || 0),'점'].join(''));
        if ((parseFloat(document.getElementById("sc").value) || 0) > best) {
          best = (parseFloat(document.getElementById("sc").value) || 0);
          bestName = document.getElementById("nm").value.trim();
        }
        sum = 0;
        for (var s_index in scores) {
          s = scores[s_index];
          sum = (typeof sum === 'number' ? sum : 0) + s;
        }
        document.getElementById("avg").textContent = '평균: ' + String(Math.round((sum / scores.length) * 10) / 10);
        document.getElementById("top").textContent = ['최고: ',bestName,' (',best,')'].join('');
        document.getElementById("nm").value = '';
        document.getElementById("sc").value = '';
      }
    });

    scores = [];
    best = -1;
  </script>
</body>
</html>
