  <h2 id="sc">Score: 0</h2>
  <button id="go">Click!</button>
  <p id="best">Best: 0</p>
  <script>
    var __mem = {};
    function __save(k, v) {
      k = 'ffb:' + k;
      __mem[k] = v;
      try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {}
    }
    function __load(k, d) {
      k = 'ffb:' + k;
      try {
        var s = localStorage.getItem(k);
        if (s !== null) return JSON.parse(s);
      } catch (e) {}
      return k in __mem ? __mem[k] : d;
    }

    var score;

    document.getElementById("go").addEventListener('click', function () {
      score = (typeof score === 'number' ? score : 0) + 1;
      document.getElementById("sc").textContent = 'Score: ' + String(score);
      if (score > __load('best', 0)) {
        __save('best', score);
        document.getElementById("best").textContent = 'Best: ' + String(score);
      }
    });

    score = 0;
    document.getElementById("best").textContent = 'Best: ' + String(__load('best', 0));
  </script>
