      document.getElementById("pic").textContent = pics[(i - 1)];
      document.getElementById("pos").textContent = [i,' / ',pics.length].join('');
    }

    document.getElementById("next").addEventListener('click', function () {
      i = (typeof i === 'number' ? i : 0) + 1;
      if (i > pics.length) {
        i = 1;
      }
      show();
    });
    document.getElementById("prev").addEventListener('click', function () {
      i = (typeof i === 'number' ? i : 0) + -1;
      if (i < 1) {
        i = pics.length;
      }
      show();
    });

    pics = ['🐶', '🐱', '🐰', '🦊', '🐼'];
    i = 1;
    show();
  </script>
