    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var left, c, cnt;

    document.getElementById("goBtn").addEventListener('click', function () {
      document.getElementById("coinList").textContent = '';
      left = (parseFloat(document.getElementById("moneyBox").value) || 0);
      var c_list = [500, 100, 50, 10];
      for (var c_index in c_list) {
        c = c_list[c_index];
        cnt = Math.floor(left / c);
        left = left % c;
        if (cnt > 0) {
          __add("coinList", [c,'원 × ',cnt,'개'].join(''));
        }
      }
    });
  </script>
