  <meta charset="UTF-8">
  <title>로또 번호 뽑기</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #fff8e1; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
    ul { display: inline-block; text-align: left; }
  </style>
</head>
<body>
  <h1 id="title">로또 번호 뽑기</h1>
  <h2 id="nums">? ? ? ? ? ?</h2>
  <button id="go">번호 뽑기</button>
  <p id="bonusText"></p>
  <ul id="past"></ul>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var picked, x, line;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    function listsGetSortCompare(type, direction) {
      var compareFuncs = {
        'NUMERIC': function(a, b) {
            return Number(a) - Number(b); },
        'TEXT': function(a, b) {
            return String(a) > String(b) ? 1 : -1; },
        'IGNORE_CASE': function(a, b) {
            return String(a).toLowerCase() > String(b).toLowerCase() ? 1 : -1; },
      };
      var compare = compareFuncs[type];
      return function(a, b) { return compare(a, b) * direction; };
    }

    document.getElementById("go").addEventListener('click', function () {
      picked = [];
      while (picked.length < 6) {
        x = mathRandomInt(1, 45);
        if (picked.indexOf(x) + 1 == 0) {
          picked.push(x);
        }
      }
      picked = picked.slice().sort(listsGetSortCompare("NUMERIC", 1));
      line = '';
      for (var x_index in picked) {
        x = picked[x_index];
        line = [line,x,'  '].join('');
      }
      document.getElementById("nums").textContent = line;
      __beep(392.00, 0.2);
      x = mathRandomInt(1, 45);
      while (picked.indexOf(x) + 1 > 0) {
        x = mathRandomInt(1, 45);
      }
      document.getElementById("bonusText").textContent = '보너스: ' + String(x);
      __add("past", line);
    });
  </script>
</body>
</html>
