        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("sky").addEventListener('click', function (e) {
      __pos(e, this);
      col = 'hsl(' + Math.floor(Math.random() * 360) + ', 80%, 60%)';
      for (var count = 0; count < 14; count++) {
        __circle("sky", __mx + mathRandomInt(-40, 40), __my + mathRandomInt(-40, 40), mathRandomInt(2, 6), col);
      }
      __circle("sky", __mx, __my, 8, "#ffffff");
