  <script>
    var __mem = {};
    function __save(k, v) {
      k = 'ffb:' + k;
      __mem[k] = v;
      try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {}
    }
    function __load(k, d) {
      k = 'ffb:' + k;
      try {
        var s = localStorage.getItem(k);
        if (s !== null) return JSON.parse(s);
      } catch (e) {}
      return k in __mem ? __mem[k] : d;
    }

    document.getElementById("save").addEventListener('click', function () {
      __save('name', document.getElementById("nm").value);
      document.getElementById("hello").textContent = String(document.getElementById("nm").value) + '님, 기억할게요!';
    });

    if (__load('name', '') == '') {
      document.getElementById("hello").textContent = '처음 보네요! 이름이 뭐예요?';
    } else {
      document.getElementById("hello").textContent = ['다시 왔네요, ',__load('name', ''),'님!'].join('');
