  </style>
</head>
<body>
  <h2 id="title">Catch the Fruit</h2>
  <div id="info" class="box row">
    <h3 id="sc">Score: 0</h3>
    <h3 id="lv">Lives: 3</h3>
  </div>
  <p id="hint">Move the basket with the left and right arrows</p>
  <h1 id="drop">🍊</h1>
  <h1 id="bsk">🧺</h1>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __move(name, x, y) {
      var s = $(name).style;
      s.position = 'absolute';
      s.left = x + 'px';
      s.top = y + 'px';
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }
    function __nudge(name, dx, dy) {
      var el = $(name), s = el.style;
      if (s.position !== 'absolute') {
        var r = el.getBoundingClientRect();
        s.position = 'absolute';
        s.left = (r.left + window.pageXOffset) + 'px';
        s.top = (r.top + window.pageYOffset) + 'px';
      }
      s.left = ((parseFloat(s.left) || 0) + dx) + 'px';
      s.top = ((parseFloat(s.top) || 0) + dy) + 'px';
    }
    function __where(name, axis) {
      var r = $(name).getBoundingClientRect();
      return Math.round(axis === 'x' ? r.left + window.pageXOffset : r.top + window.pageYOffset);
    }
    function __hit(a, b) {
      var p = $(a).getBoundingClientRect(), q = $(b).getBoundingClientRect();
      return p.left < q.right && p.right > q.left && p.top < q.bottom && p.bottom > q.top;
    }
    function __stay(name) {
      var el = $(name), s = el.style, d = document.documentElement;
      if (s.position !== 'absolute') return;
      var x = Math.max(0, Math.min(parseFloat(s.left) || 0, d.clientWidth - el.offsetWidth));
      var y = Math.max(0, Math.min(parseFloat(s.top) || 0, d.clientHeight - el.offsetHeight));
      s.left = x + 'px';
      s.top = y + 'px';
    }
    var __timers = [];

    var score, lives;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function respawn() {
      __move("drop", mathRandomInt(20, 260), 0);
    }

    __timers.push(setInterval(function () {
      __nudge("drop", 0, 6);
      if (__hit("drop", "bsk")) {
        score = (typeof score === 'number' ? score : 0) + 1;
        document.getElementById("sc").textContent = 'Score: ' + String(score);
        respawn();
      } else if (__where("drop", "y") > 360) {
        lives = (typeof lives === 'number' ? lives : 0) + -1;
        document.getElementById("lv").textContent = 'Lives: ' + String(lives);
        respawn();
      }
      if (lives <= 0) {
        __timers.forEach(clearInterval);
        document.getElementById("hint").textContent = 'Game over!';
        __show("drop", "hide");
      }
    }, 50));
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowLeft") {
        e.preventDefault();
        __nudge("bsk", -25, 0);
        __stay("bsk");
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowRight") {
        e.preventDefault();
        __nudge("bsk", 25, 0);
        __stay("bsk");
      }
    });

    score = 0;
    lives = 3;
    __move("drop", mathRandomInt(20, 260), 0);
    __move("bsk", 140, 330);
  </script>
</body>
</html>
