      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function newProblem() {
      a = mathRandomInt(1, 10);
      b = mathRandomInt(1, 10);
      document.getElementById("problem").textContent = [a,' + ',b,' = ?'].join('');
      document.getElementById("ans").value = '';
    }

