    canvas { max-width: 100%; background: #ffffff; border: 1px solid #d1d5db; border-radius: 8px; touch-action: manipulation; }
  </style>
</head>
<body>
  <canvas id="clock" width="240" height="240"></canvas>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    var __timers = [];
    function __pen(name) { return $(name).getContext('2d'); }
    function __clear(name) { var c = $(name); __pen(name).clearRect(0, 0, c.width, c.height); }
    function __circle(name, x, y, r, color) { var g = __pen(name); g.fillStyle = color; g.beginPath(); g.arc(x, y, Math.max(0, r), 0, Math.PI * 2); g.fill(); }
    function __line(name, x1, y1, x2, y2, color) { var g = __pen(name); g.strokeStyle = color; g.lineWidth = 3; g.lineCap = 'round'; g.beginPath(); g.moveTo(x1, y1); g.lineTo(x2, y2); g.stroke(); }

    // 이 함수를 설명하세요...
    function tick() {
      __clear("clock");
      __circle("clock", 120, 120, 110, "#ffffff");
      __line("clock", 120, 120, (120 + 55 * Math.sin(new Date().getHours() * Math.PI / 6)), (120 - 55 * Math.cos(new Date().getHours() * Math.PI / 6)), "#111111");
      __line("clock", 120, 120, (120 + 85 * Math.sin(new Date().getMinutes() * Math.PI / 30)), (120 - 85 * Math.cos(new Date().getMinutes() * Math.PI / 30)), "#111111");
      __line("clock", 120, 120, (120 + 95 * Math.sin(new Date().getSeconds() * Math.PI / 30)), (120 - 95 * Math.cos(new Date().getSeconds() * Math.PI / 30)), "#ef4444");
      __circle("clock", 120, 120, 6, "#111111");
    }

    __timers.push(setInterval(function () {
      tick();
    }, 1000));

    tick();
  </script>
</body>
</html>
