  <h2 id="question"></h2>
  <div id="row1" class="box row">
    <input id="answerBox" type="number" placeholder="답">
    <button id="checkBtn">확인</button>
  </div>
  <p id="livesText">목숨: 3</p>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var a, lives, b;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function newQuestion() {
      a = mathRandomInt(1, 10);
      b = mathRandomInt(1, 10);
      document.getElementById("question").textContent = [a,' + ',b,' = ?'].join('');
    }

    document.getElementById("checkBtn").addEventListener('click', function () {
      if ((parseFloat(document.getElementById("answerBox").value) || 0) == a + b) {
        __beep(523.25, 0.2);
      } else {
        lives = (typeof lives === 'number' ? lives : 0) + -1;
        __beep(261.63, 0.4);
      }
      document.getElementById("livesText").textContent = '목숨: ' + String(lives);
      if (lives <= 0) {
        document.getElementById("question").textContent = '게임 오버';
        __show("row1", "hide");
      } else {
        newQuestion();
      }
    });

    lives = 3;
    newQuestion();
  </script>
</body>
