    input { font: inherit; padding: 9px 12px; margin: 4px; border: 1px solid #9ca3af; border-radius: 9px; }
    ul { display: inline-block; text-align: left; }
  </style>
</head>
<body>
  <h1 id="title1">Shopping list</h1>
  <input id="itemBox" type="text" placeholder="Item">
  <button id="addBtn">Add</button>
  <button id="undoBtn">Remove last</button>
  <button id="sortBtn">Sort A-Z</button>
  <ul id="shopList"></ul>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var items, it;

    // 이 함수를 설명하세요...
    function redraw() {
      document.getElementById("shopList").textContent = '';
      for (var it_index in items) {
        it = items[it_index];
        __add("shopList", it);
      }
    }

    function listsGetSortCompare(type, direction) {
      var compareFuncs = {
        'NUMERIC': function(a, b) {
            return Number(a) - Number(b); },
        'TEXT': function(a, b) {
            return String(a) > String(b) ? 1 : -1; },
        'IGNORE_CASE': function(a, b) {
            return String(a).toLowerCase() > String(b).toLowerCase() ? 1 : -1; },
      };
      var compare = compareFuncs[type];
      return function(a, b) { return compare(a, b) * direction; };
    }

    document.getElementById("addBtn").addEventListener('click', function () {
      if (!!document.getElementById("itemBox").value.length) {
        items.push(document.getElementById("itemBox").value);
        document.getElementById("itemBox").value = '';
        redraw();
      }
    });
    document.getElementById("undoBtn").addEventListener('click', function () {
      if (!!items.length) {
        items.pop();
        redraw();
      }
    });
    document.getElementById("sortBtn").addEventListener('click', function () {
      items = items.slice().sort(listsGetSortCompare("IGNORE_CASE", 1));
      redraw();
    });

    items = [];
  </script>
</body>
</html>
