      if (e.key === " ") {
        e.preventDefault();
        색 = 'hsl(' + Math.floor(Math.random() * 360) + ', 80%, 60%)';
      }
    });
    document.getElementById("그림판1").addEventListener('click', function (e) {
      __pos(e, this);
      x = __mx;
      y = __my;
