  </style>
</head>
<body>
  <h2 id="title">Palindrome Checker</h2>
  <input id="w" type="text" placeholder="Word or phrase">
  <button id="go">Check</button>
  <h3 id="out"></h3>
  <script>
    var s, r, k;

    document.getElementById("go").addEventListener('click', function () {
      s = document.getElementById("w").value.trim().toLowerCase();
      r = '';
      var k_end = s.length;
      var k_inc = 1;
      if (1 > k_end) {
        k_inc = -k_inc;
      }
      for (k = 1; k_inc >= 0 ? k <= k_end : k >= k_end; k += k_inc) {
        r = String(s.charAt((k - 1))) + String(r);
      }
      if (!s.length) {
        document.getElementById("out").textContent = '';
      } else if (r == s) {
        document.getElementById("out").textContent = '✅ Palindrome! ' + String(r);
      } else {
        document.getElementById("out").textContent = '❌ Not a palindrome. Reversed: ' + String(r);
      }
    });
  </script>
</body>
</html>
