    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h2 id="title">반 티셔츠 투표</h2>
  <div id="choices" class="box row">
    <button id="o0">A안</button>
    <button id="o1">B안</button>
  </div>
  <p id="r0">A안: 0</p>
  <p id="r1">B안: 0</p>
  <p id="total">총 0표</p>
  <script>
    var name2, cnt, k, votes, sum, top2, x, names;

    // 이 함수를 설명하세요...
    function lineOf(name2, cnt) {
      return [name2,': ',cnt,'표'].join('');
    }

    // 이 함수를 설명하세요...
    function cast(k) {
      votes[(k - 1)] = votes[(k - 1)] + 1;
      sum = 0;
      for (var x_index in votes) {
        x = votes[x_index];
        sum = (typeof sum === 'number' ? sum : 0) + x;
      }
      document.getElementById("r0").textContent = lineOf('A안', votes[0]);
      document.getElementById("r1").textContent = lineOf('B안', votes[1]);
      document.getElementById("total").textContent = ['총 ',sum,'표'].join('');
    }

    function listsRepeat(value, n) {
      var array = [];
      for (var i = 0; i < n; i++) {
        array[i] = value;
      }
      return array;
    }

    document.getElementById("o0").addEventListener('click', function () {
      cast(1);
    });
    document.getElementById("o1").addEventListener('click', function () {
      cast(2);
    });

    votes = listsRepeat(0, 2);
    top2 = 1;
    names = ['A안', 'B안'];
  </script>
</body>
</html>
