  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }

    var pick, qs, right, i, ans;

    // 이 함수를 설명하세요...
    function answer(pick) {
      if (pick == ans[(i - 1)]) {
        right = (typeof right === 'number' ? right : 0) + 1;
      }
      i = (typeof i === 'number' ? i : 0) + 1;
      if (i > 5) {
        document.getElementById("qText").textContent = ['5문제 중 ',right,'개 맞혔어요'].join('');
        __show("btns", "hide");
      } else {
        document.getElementById("qText").textContent = qs[(i - 1)];
      }
    }

    document.getElementById("oBtn").addEventListener('click', function () {
      answer('O');
    });
    document.getElementById("xBtn").addEventListener('click', function () {
