<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>소수 판별기</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #dcfce7; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
    input { font: inherit; padding: 9px 12px; margin: 4px; border: 1px solid #9ca3af; border-radius: 9px; }
  </style>
</head>
<body>
  <h1 id="title1">소수일까?</h1>
  <input id="numBox" type="number" placeholder="자연수를 써요">
  <button id="checkBtn">확인</button>
  <h2 id="result"></h2>
  <script>
    var n;

    function mathIsPrime(n) {
      // https://en.wikipedia.org/wiki/Primality_test#Naive_methods
      if (n == 2 || n == 3) {
        return true;
      }
      // False if n is NaN, negative, is 1, or not whole.
      // And false if n is divisible by 2 or 3.
      if (isNaN(n) || n <= 1 || n % 1 !== 0 || n % 2 === 0 || n % 3 === 0) {
        return false;
      }
      // Check all the numbers of form 6k +/- 1, up to sqrt(n).
      for (var x = 6; x <= Math.sqrt(n) + 1; x += 6) {
        if (n % (x - 1) === 0 || n % (x + 1) === 0) {
          return false;
        }
      }
      return true;
    }

    document.getElementById("checkBtn").addEventListener('click', function () {
      n = (parseFloat(document.getElementById("numBox").value) || 0);
      if (n < 2) {
        document.getElementById("result").textContent = '2 이상의 자연수를 써 주세요';
        document.getElementById("result").style.color = "#9ca3af";
      } else if (mathIsPrime(n)) {
        document.getElementById("result").textContent = String(n) + '은(는) 소수예요!';
        document.getElementById("result").style.color = "#22c55e";
      } else {
        document.getElementById("result").textContent = String(n) + '은(는) 소수가 아니에요';
        document.getElementById("result").style.color = "#ef4444";
      }
    });
  </script>
</body>
</html>
