  <h2 id="title">스톱워치</h2>
  <h1 id="clock">0.0</h1>
  <div id="btns" class="box row">
    <button id="go">시작</button>
    <button id="stop">멈춤</button>
    <button id="lap">랩</button>
    <button id="reset">초기화</button>
  </div>
  <p id="bestText">가장 빠른 랩: -</p>
  <ul id="laps"></ul>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }
    var __timers = [];

    var running, t, lapTime, lastLap, n, bestLap;

    document.getElementById("go").addEventListener('click', function () {
      running = true;
    });
    document.getElementById("stop").addEventListener('click', function () {
      running = false;
    });
    document.getElementById("lap").addEventListener('click', function () {
      if (running) {
        lapTime = Math.round((t - lastLap) * 10) / 10;
        lastLap = t;
        n = (typeof n === 'number' ? n : 0) + 1;
        __add("laps", ['랩',' ',n,': ',lapTime,'초'].join(''));
        if (bestLap == 0 || lapTime < bestLap) {
          bestLap = lapTime;
          document.getElementById("bestText").textContent = ['가장 빠른 랩: ',bestLap,'초'].join('');
        }
      }
    });
    document.getElementById("reset").addEventListener('click', function () {
      running = false;
      t = 0;
      lastLap = 0;
      n = 0;
      bestLap = 0;
      document.getElementById("clock").textContent = '0.0';
      document.getElementById("laps").textContent = '';
      document.getElementById("bestText").textContent = '가장 빠른 랩: -';
    });
    __timers.push(setInterval(function () {
      if (running) {
        t = Math.round((t + 0.1) * 10) / 10;
        document.getElementById("clock").textContent = t;
      }
    }, 100));

    running = false;
    t = 0;
    lastLap = 0;
    n = 0;
    bestLap = 0;
    document.getElementById("clock").textContent = '0.0';
    document.getElementById("laps").textContent = '';
    document.getElementById("bestText").textContent = '가장 빠른 랩: -';
  </script>
</body>
</html>
