  <button id="goBtn">비교</button>
  <h2 id="out"></h2>
  <script>
    var a, b, c;

    function listsGetSortCompare(type, direction) {
      var compareFuncs = {
        'NUMERIC': function(a, b) {
            return Number(a) - Number(b); },
        'TEXT': function(a, b) {
            return String(a) > String(b) ? 1 : -1; },
        'IGNORE_CASE': function(a, b) {
            return String(a).toLowerCase() > String(b).toLowerCase() ? 1 : -1; },
      };
      var compare = compareFuncs[type];
      return function(a, b) { return compare(a, b) * direction; };
    }

    // 이 함수를 설명하세요...
    function biggest(a, b, c) {
      return [a, b, c].slice().sort(listsGetSortCompare("NUMERIC", 1)).slice(-1)[0];
    }

    document.getElementById("goBtn").addEventListener('click', function () {
      document.getElementById("out").textContent = '가장 큰 수: ' + String(biggest((parseFloat(document.getElementById("aBox").value) || 0), (parseFloat(document.getElementById("bBox").value) || 0), (parseFloat(document.getElementById("cBox").value) || 0)));
    });
  </script>
