<body>
  <h2 id="info">Score: 0 · 20s</h2>
  <canvas id="cv" width="320" height="240"></canvas>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    var __mx = 0, __my = 0;
    function __pos(e, el) {
      var r = el.getBoundingClientRect();
      __mx = Math.round((e.clientX - r.left) * (el.width ? el.width / r.width : 1));
      __my = Math.round((e.clientY - r.top) * (el.height ? el.height / r.height : 1));
    }
    var __timers = [];
    function __pen(name) { return $(name).getContext('2d'); }
    function __clear(name) { var c = $(name); __pen(name).clearRect(0, 0, c.width, c.height); }
    function __circle(name, x, y, r, color) { var g = __pen(name); g.fillStyle = color; g.beginPath(); g.arc(x, y, Math.max(0, r), 0, Math.PI * 2); g.fill(); }
    function __text(name, text, x, y, color) { var g = __pen(name); g.fillStyle = color; g.font = '20px sans-serif'; g.fillText(text, x, y); }

    var s, x, t, y;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function place() {
      x = mathRandomInt(25, 295);
      y = mathRandomInt(25, 215);
      __clear("cv");
      __circle("cv", x, y, 25, "#facc15");
    }

    document.getElementById("cv").addEventListener('click', function (e) {
      __pos(e, this);
      if (Math.abs(__mx - x) < 25 && Math.abs(__my - y) < 25) {
        s = (typeof s === 'number' ? s : 0) + 1;
        place();
      }
    });
    __timers.push(setInterval(function () {
      t = (typeof t === 'number' ? t : 0) + -1;
      document.getElementById("info").textContent = ['Score: ',s,' · ',t,'s'].join('');
      if (t == 0) {
        __timers.forEach(clearInterval);
        x = -100;
        __clear("cv");
