    .box { display: flex; flex-direction: column; gap: 8px; padding: 12px; margin: 8px 0; border-radius: 12px; align-items: center; }
    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h1 id="title">🐊 어느 쪽이 더 클까?</h1>
  <h1 id="prob"></h1>
  <div id="r" class="box row">
    <button id="lt">&lt;</button>
    <button id="eq">=</button>
    <button id="gt">&gt;</button>
  </div>
  <h2 id="res"></h2>
  <script>
    var ok, a, b;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function newQ() {
      a = mathRandomInt(1, 20);
      b = mathRandomInt(1, 20);
      document.getElementById("prob").textContent = [a,'  ?  ',b].join('');
    }

    // 이 함수를 설명하세요...
    function answer(ok) {
      if (ok) {
        document.getElementById("res").textContent = '정답! 🎉';
        newQ();
      } else {
        document.getElementById("res").textContent = '다시 봐 봐 🤔';
      }
    }

    document.getElementById("lt").addEventListener('click', function () {
      answer(a < b);
    });
    document.getElementById("eq").addEventListener('click', function () {
      answer(a == b);
    });
    document.getElementById("gt").addEventListener('click', function () {
      answer(a > b);
    });

    newQ();
  </script>
</body>
</html>
