      if (c == 7) {
        document.getElementById("msg").textContent = '🔥 이번 주 전부 성공!';
        __beep(523.25, 0.3);
      } else {
        document.getElementById("msg").textContent = '';
      }
    }

    function listsRepeat(value, n) {
      var array = [];
      for (var i = 0; i < n; i++) {
        array[i] = value;
      }
      return array;
    }

    document.getElementById("d0").addEventListener('click', function () {
      tick(1);
      document.getElementById("d0").textContent = done[0] ? '월 ✅' : '월 ⬜';
    });
    document.getElementById("d1").addEventListener('click', function () {
      tick(2);
