      var x = Math.max(0, Math.min(parseFloat(s.left) || 0, d.clientWidth - el.offsetWidth));
      var y = Math.max(0, Math.min(parseFloat(s.top) || 0, d.clientHeight - el.offsetHeight));
      s.left = x + 'px';
      s.top = y + 'px';
    }
    var __timers = [];

    var score, dx, dy;

    __timers.push(setInterval(function () {
      __nudge("ball", dx, dy);
      if (__where("ball", "x") > 240 || __where("ball", "x") < 0) {
        dx = 0 - dx;
      }
      if (__where("ball", "y") < 60) {
        dy = 5;
      }
      if (__hit("ball", "pad")) {
        dy = -5;
        score = (typeof score === 'number' ? score : 0) + 1;
        document.getElementById("sc").textContent = 'Returns: ' + String(score);
      } else if (__where("ball", "y") > 340) {
        __timers.forEach(clearInterval);
        document.getElementById("hint").textContent = 'Missed! Game over';
      }
    }, 30));
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowLeft") {
        e.preventDefault();
        __nudge("pad", -25, 0);
        __stay("pad");
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowRight") {
        e.preventDefault();
        __nudge("pad", 25, 0);
        __stay("pad");
      }
    });

    score = 0;
    dx = 4;
    dy = 5;
    __move("ball", 120, 100);
    __move("pad", 110, 300);
