  <h1 id="title">🛒 장보기 목록</h1>
  <div id="row1" class="box row">
    <input id="itemIn" type="text" placeholder="물건 이름">
    <input id="priceIn" type="number" placeholder="가격">
    <button id="addBtn">담기</button>
  </div>
  <ul id="shopList"></ul>
  <h2 id="totalTxt">합계: 0원</h2>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var sum;

    document.getElementById("addBtn").addEventListener('click', function () {
      if (!document.getElementById("itemIn").value.trim().length) {
        alert('물건 이름을 써 주세요');
      } else {
        __add("shopList", [document.getElementById("itemIn").value,' - ',(parseFloat(document.getElementById("priceIn").value) || 0),'원'].join(''));
