      if (left <= 0) {
        __timers.forEach(clearInterval);
        if (score > __load('최고점', 0)) {
          __save('최고점', score);
          document.getElementById("최고기록").textContent = '새 기록! ' + String(score);
        }
        alert('끝! 점수는 ' + String(score));
      }
    }, 1000));

    x = 160;
