    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var n, d;

    document.getElementById("addBtn").addEventListener('click', function () {
      if (!!document.getElementById("taskBox").value.length) {
        __add("taskList", document.getElementById("taskBox").value);
        n = (typeof n === 'number' ? n : 0) + 1;
        document.getElementById("taskBox").value = '';
        document.getElementById("countText").textContent = ['할 일 ',n,'개 / 끝낸 것 ',d,'개'].join('');
      }
    });
    document.getElementById("doneBtn").addEventListener('click', function () {
      if (d < n) {
        d = (typeof d === 'number' ? d : 0) + 1;
        document.getElementById("countText").textContent = ['할 일 ',n,'개 / 끝낸 것 ',d,'개'].join('');
        if (d == n) {
          document.getElementById("countText").textContent = '다 했어요! 최고 👏';
        }
      }
    });

    n = 0;
    d = 0;
  </script>
