<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>Timer</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #111111; color: #f1f5f9; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
    input { font: inherit; padding: 9px 12px; margin: 4px; border: 1px solid #9ca3af; border-radius: 9px; }
    .box { display: flex; flex-direction: column; gap: 8px; padding: 12px; margin: 8px 0; border-radius: 12px; align-items: center; }
    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h2 id="title">Timer</h2>
  <h1 id="clock">0:00</h1>
  <div id="inputs" class="box row">
    <input id="minBox" type="number" placeholder="min">
    <input id="secBox" type="number" placeholder="sec">
  </div>
  <div id="btns" class="box row">
    <button id="go">Start</button>
    <button id="pause">Pause</button>
    <button id="reset">Reset</button>
  </div>
  <p id="msg"></p>
  <script>
    var __timers = [];
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var s, left, running;

    // 이 함수를 설명하세요...
    function showTime() {
      s = left % 60;
      document.getElementById("clock").textContent = [Math.floor(left / 60),s < 10 ? ':0' : ':',s].join('');
    }

    document.getElementById("go").addEventListener('click', function () {
      if (left == 0) {
        left = (parseFloat(document.getElementById("minBox").value) || 0) * 60 + (parseFloat(document.getElementById("secBox").value) || 0);
      }
      running = left > 0;
      document.getElementById("msg").textContent = '';
      showTime();
    });
    document.getElementById("pause").addEventListener('click', function () {
      running = false;
    });
    document.getElementById("reset").addEventListener('click', function () {
      running = false;
      left = 0;
      showTime();
      document.getElementById("msg").textContent = '';
    });
    __timers.push(setInterval(function () {
      if (running && left > 0) {
        left = (typeof left === 'number' ? left : 0) + -1;
        showTime();
        if (left == 0) {
          running = false;
          document.getElementById("msg").textContent = '⏰ Time\'s up!';
          __beep(523.25, 0.8);
        }
      }
    }, 1000));

    left = 0;
    running = false;
  </script>
</body>
</html>
