  <h1 id="cnt">0 / 8</h1>
  <button id="add">+1 Glas</button>
  <button id="reset">Zurücksetzen</button>
  <p id="msg"></p>
  <script>
    var __mem = {};
    function __save(k, v) {
      k = 'ffb:' + k;
      __mem[k] = v;
      try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {}
    }
    function __load(k, d) {
      k = 'ffb:' + k;
      try {
        var s = localStorage.getItem(k);
        if (s !== null) return JSON.parse(s);
      } catch (e) {}
      return k in __mem ? __mem[k] : d;
    }

    var glass;

    // 이 함수를 설명하세요...
    function show() {
      document.getElementById("cnt").textContent = String(glass) + ' / 8';
      __save('glass', glass);
      if (glass >= 8) {
        document.getElementById("msg").textContent = 'Ziel erreicht! 🎉';
      } else {
        document.getElementById("msg").textContent = ['Noch ',8 - glass,' Gläser'].join('');
      }
    }

    document.getElementById("add").addEventListener('click', function () {
      glass = (typeof glass === 'number' ? glass : 0) + 1;
      show();
    });
    document.getElementById("reset").addEventListener('click', function () {
      glass = 0;
      show();
    });

    glass = __load('glass', 0);
    show();
  </script>
</body>
