      if (run > best) {
        best = run;
      }
      cur = nx;
      document.getElementById("card").textContent = cur;
      document.getElementById("st").textContent = ['연속: ',run,' · 최고: ',best].join('');
    }

    document.getElementById("hi").addEventListener('click', function () {
      guess(true);
    });
    document.getElementById("lo").addEventListener('click', function () {
      guess(false);
    });

    cur = mathRandomInt(1, 10);
