      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var n, c, k;

    document.getElementById("findBtn").addEventListener('click', function () {
      n = (parseFloat(document.getElementById("nBox").value) || 0);
      document.getElementById("numList").textContent = '';
      c = 0;
      document.getElementById("label").textContent = String(n) + '의 배수 (100까지)';
      if (n > 0) {
        for (k = 1; k <= 100; k++) {
          if (k % n == 0) {
            __add("numList", k);
            c = (typeof c === 'number' ? c : 0) + 1;
          }
        }
      }
      document.getElementById("countText").textContent = '개수: ' + String(c);
    });
