      document.getElementById('score').textContent = '점수: ' + score;
      index += 1;
      if (index < quiz.length) {
        ask();
      } else {
        document.getElementById('question').textContent = '끝! ' + quiz.length + '문제 중 ' + score + '개 맞혔어요';
