    var __timers = [];

    var t;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    __timers.push(setInterval(function () {
      __nudge("foe", 0, 8);
      if (__where("foe", "y") > 380) {
        __move("foe", mathRandomInt(20, 260), 0);
      }
      if (__hit("foe", "me")) {
        __timers.forEach(clearInterval);
        document.getElementById("hint").textContent = 'Hit! The end';
