    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var i;

    document.getElementById("showBtn").addEventListener('click', function () {
      document.getElementById("table").textContent = '';
      for (i = 1; i <= 9; i++) {
        __add("table", [(parseFloat(document.getElementById("dan").value) || 0),' × ',i,' = ',(parseFloat(document.getElementById("dan").value) || 0) * i].join(''));
