        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var x, k;

    document.getElementById("go").addEventListener('click', function () {
      document.getElementById("out").textContent = '';
      x = Math.min(Math.max(Math.floor((parseFloat(document.getElementById("n").value) || 0)), 1), 1000);
      k = 0;
      __add("out", x);
      while (x > 1) {
        if (x % 2 === 0) {
          x = x / 2;
        } else {
          x = x * 3 + 1;
        }
        k = (typeof k === 'number' ? k : 0) + 1;
        __add("out", x);
      }
      document.getElementById("steps").textContent = ['Reached 1 in ',k,' steps'].join('');
    });
  </script>
</body>
</html>
