<head>
  <meta charset="UTF-8">
  <title>과학 개념 카드</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #e0f2fe; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
    .box { display: flex; flex-direction: column; gap: 8px; padding: 12px; margin: 8px 0; border-radius: 12px; align-items: center; }
    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h2 id="title">과학 개념 카드</h2>
  <div id="card" class="box" style="background:#ffffff">
    <h1 id="front">광합성</h1>
    <h3 id="back">빛으로 양분을 만드는 것</h3>
  </div>
  <div id="btns" class="box row">
    <button id="flip">뜻 보기</button>
    <button id="next">다음</button>
    <button id="know">외웠어요 ✅</button>
  </div>
  <p id="count">외운 단어: 0</p>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }

    var w, i, got, m;

    document.getElementById("flip").addEventListener('click', function () {
      __show("back", "toggle");
    });
    document.getElementById("next").addEventListener('click', function () {
      i = i % w.length + 1;
      document.getElementById("front").textContent = w[(i - 1)];
      document.getElementById("back").textContent = m[(i - 1)];
      __show("back", "hide");
    });
    document.getElementById("know").addEventListener('click', function () {
