    <button id="i1">바나나 2500원</button>
    <button id="i2">우유 2800원</button>
  </div>
  <ul id="basket"></ul>
  <h3 id="total">합계: 0원</h3>
  <p id="countText">담은 개수: 0</p>
  <p id="note"></p>
  <button id="clearBtn">비우기</button>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var name2, price, sum, cnt, pay;

    // 이 함수를 설명하세요...
    function addItem(name2, price) {
      __add("basket", [name2,' ',price,'원'].join(''));
      sum = (typeof sum === 'number' ? sum : 0) + price;
      cnt = (typeof cnt === 'number' ? cnt : 0) + 1;
      if (sum >= 15000) {
        pay = sum * 0.95;
        document.getElementById("note").textContent = '할인 적용! -5%';
      } else {
        pay = sum;
        document.getElementById("note").textContent = '';
      }
      document.getElementById("total").textContent = ['합계: ',pay,'원'].join('');
      document.getElementById("countText").textContent = '담은 개수: ' + String(cnt);
    }

