  <button id="pickBtn">뽑기</button>
  <h2 id="out"></h2>
  <script>
    var names, first, second;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("pickBtn").addEventListener('click', function () {
      names = ['민준', '서윤', '하준', '지우', '예준'];
      first = names.splice((mathRandomInt(1, names.length) - 1), 1)[0];
      second = names.splice((mathRandomInt(1, names.length) - 1), 1)[0];
      document.getElementById("out").textContent = [first,', ',second].join('');
    });
  </script>
