<body>
  <h2 id="title1">무지개 하늘</h2>
  <canvas id="sky" width="320" height="180"></canvas>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __pen(name) { return $(name).getContext('2d'); }
    function __rect(name, x, y, w, h, color) { var g = __pen(name); g.fillStyle = color; g.fillRect(x, y, w, h); }
    function __circle(name, x, y, r, color) { var g = __pen(name); g.fillStyle = color; g.beginPath(); g.arc(x, y, Math.max(0, r), 0, Math.PI * 2); g.fill(); }

    var cols, i;

    __rect("sky", 0, 0, 320, 180, "#38bdf8");
    cols = ["#ef4444", "#f97316", "#facc15", "#22c55e", "#3b82f6", "#a855f7"];
    var i_end = cols.length;
    var i_inc = 1;
    if (1 > i_end) {
      i_inc = -i_inc;
    }
    for (i = 1; i_inc >= 0 ? i <= i_end : i >= i_end; i += i_inc) {
      __circle("sky", 160, 180, 168 - i * 18, cols[(i - 1)]);
    }
    __circle("sky", 160, 180, 42, "#38bdf8");
    __circle("sky", 280, 40, 25, "#ffc93c");
  </script>
</body>
