    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var icons, coin, a, b, c;

    function listsGetRandomItem(list, remove) {
      var x = Math.floor(Math.random() * list.length);
      if (remove) {
        return list.splice(x, 1)[0];
      } else {
        return list[x];
      }
    }

    document.getElementById("spin").addEventListener('click', function () {
      if (coin > 0) {
        coin = (typeof coin === 'number' ? coin : 0) + -1;
        a = listsGetRandomItem(icons, false);
        b = listsGetRandomItem(icons, false);
        c = listsGetRandomItem(icons, false);
        document.getElementById("r1").textContent = a;
        document.getElementById("r2").textContent = b;
        document.getElementById("r3").textContent = c;
        if (a == b && b == c) {
          coin = (typeof coin === 'number' ? coin : 0) + 10;
          document.getElementById("msg").textContent = '🎉 잭팟!';
          __beep(523.25, 0.5);
        } else if (a == b || b == c || a == c) {
          coin = (typeof coin === 'number' ? coin : 0) + 2;
          document.getElementById("msg").textContent = '두 개 같아요!';
        } else {
          document.getElementById("msg").textContent = '꽝';
        }
        document.getElementById("coins").textContent = '코인: ' + String(coin);
      }
    });

    icons = ['🍒', '🍋', '⭐', '🔔'];
    coin = 10;
  </script>
