  <script>
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var picked, x, line;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    function listsGetSortCompare(type, direction) {
      var compareFuncs = {
        'NUMERIC': function(a, b) {
            return Number(a) - Number(b); },
        'TEXT': function(a, b) {
            return String(a) > String(b) ? 1 : -1; },
        'IGNORE_CASE': function(a, b) {
            return String(a).toLowerCase() > String(b).toLowerCase() ? 1 : -1; },
      };
      var compare = compareFuncs[type];
      return function(a, b) { return compare(a, b) * direction; };
    }

    document.getElementById("go").addEventListener('click', function () {
      picked = [];
      while (picked.length < 6) {
        x = mathRandomInt(1, 45);
        if (picked.indexOf(x) + 1 == 0) {
          picked.push(x);
        }
      }
      picked = picked.slice().sort(listsGetSortCompare("NUMERIC", 1));
      line = '';
      for (var x_index in picked) {
        x = picked[x_index];
        line = [line,x,'  '].join('');
      }
      document.getElementById("nums").textContent = line;
      __beep(392.00, 0.2);
    });
  </script>
