      x = (x + 300) % 300;
      y = (y + 300) % 300;
      __clear("board");
      __circle("board", x, y, 15, "#ec4899");
    }

    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowUp") {
        e.preventDefault();
        y = (typeof y === 'number' ? y : 0) + -10;
        draw();
