    input { font: inherit; padding: 9px 12px; margin: 4px; border: 1px solid #9ca3af; border-radius: 9px; }
  </style>
</head>
<body>
  <h2 id="title">🔢 숫자 맞히기</h2>
  <p id="hint">1부터 100 사이의 숫자를 맞혀 보세요</p>
  <input id="numIn" type="number" placeholder="숫자를 입력해요">
  <button id="check">확인</button>
  <h3 id="msg">숫자를 쓰고 확인을 눌러요</h3>
  <p id="triesText">시도: 0번</p>
  <button id="again">다시 하기</button>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var secret, tries, guess;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function newGame() {
      secret = mathRandomInt(1, 100);
      tries = 0;
      document.getElementById("msg").textContent = '숫자를 쓰고 확인을 눌러요';
      document.getElementById("triesText").textContent = '시도: 0번';
      document.getElementById("msg").style.color = "#111111";
      document.getElementById("numIn").value = '';
      __show("again", "hide");
      __show("check", "show");
    }

    document.getElementById("check").addEventListener('click', function () {
      if (!document.getElementById("numIn").value.length) {
        document.getElementById("msg").textContent = '먼저 숫자를 써 주세요';
        document.getElementById("msg").style.color = "#f97316";
      } else {
        guess = (parseFloat(document.getElementById("numIn").value) || 0);
        tries = (typeof tries === 'number' ? tries : 0) + 1;
        document.getElementById("triesText").textContent = ['시도: ',tries,'번'].join('');
        document.getElementById("numIn").value = '';
        if (guess < secret) {
          document.getElementById("msg").textContent = String(guess) + '보다 커요! ⬆️';
          document.getElementById("msg").style.color = "#3b82f6";
        } else if (guess > secret) {
          document.getElementById("msg").textContent = String(guess) + '보다 작아요! ⬇️';
          document.getElementById("msg").style.color = "#ef4444";
        } else {
          document.getElementById("msg").textContent = ['🎉 정답이에요! ',tries,'번 만에 맞혔어요!'].join('');
          document.getElementById("msg").style.color = "#22c55e";
          __beep(523.25, 0.3);
          __show("check", "hide");
          __show("again", "show");
        }
      }
    });
    document.getElementById("again").addEventListener('click', function () {
      newGame();
    });

    newGame();
  </script>
</body>
</html>
