    <input id="item" type="text" placeholder="준비물">
    <button id="add">추가</button>
  </div>
  <ul id="list"></ul>
  <h2 id="left">남은 준비물: 0개</h2>
  <button id="got">하나 챙겼어요</button>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var n;

    document.getElementById("add").addEventListener('click', function () {
      if (!!document.getElementById("item").value.length) {
        __add("list", document.getElementById("item").value);
        n = (typeof n === 'number' ? n : 0) + 1;
        document.getElementById("left").textContent = ['남은 준비물: ',n,'개'].join('');
      }
      document.getElementById("item").value = '';
    });
    document.getElementById("got").addEventListener('click', function () {
      if (n > 0) {
        n = (typeof n === 'number' ? n : 0) + -1;
        if (n == 0) {
          document.getElementById("left").textContent = '준비 끝! 🎒';
        } else {
          document.getElementById("left").textContent = ['남은 준비물: ',n,'개'].join('');
        }
      }
    });

