    <button id="stopBtn">Stop</button>
    <button id="resetBtn">Reset</button>
    <button id="lapBtn">Lap</button>
  </div>
  <ul id="laps"></ul>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }
    var __timers = [];

    var t, on;

    document.getElementById("startBtn").addEventListener('click', function () {
      on = true;
    });
    document.getElementById("stopBtn").addEventListener('click', function () {
      on = false;
    });
    document.getElementById("resetBtn").addEventListener('click', function () {
      on = false;
      t = 0;
      document.getElementById("time").textContent = 0;
      document.getElementById("laps").textContent = '';
    });
    document.getElementById("lapBtn").addEventListener('click', function () {
      __add("laps", t / 10);
    });
    __timers.push(setInterval(function () {
      if (on) {
        t = (typeof t === 'number' ? t : 0) + 1;
        document.getElementById("time").textContent = t / 10;
      }
    }, 100));

    t = 0;
    on = false;
  </script>
</body>
</html>
