  <h1 id="title">업다운 카드</h1>
  <h1 id="cardTx">7</h1>
  <button id="upBtn">더 크다 ⬆</button>
  <button id="downBtn">더 작다 ⬇</button>
  <h2 id="result"></h2>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __size(name, prop, v) {
      var s = $(name).style;
      if (prop === 'opacity') s.opacity = v / 100;
      else if (prop === 'rotate') s.transform = 'rotate(' + v + 'deg)';
      else s[prop] = v + 'px';
    }

    var up, card, new2, streak;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function next(up) {
      new2 = mathRandomInt(1, 13);
      document.getElementById("cardTx").textContent = new2;
      if (up && new2 > card || !up && new2 < card) {
        streak = (typeof streak === 'number' ? streak : 0) + 1;
        document.getElementById("result").textContent = '맞았어! 연속 ' + String(streak);
      } else {
        streak = 0;
        document.getElementById("result").textContent = '틀렸어! 처음부터';
      }
      card = new2;
    }

    document.getElementById("upBtn").addEventListener('click', function () {
      next(true);
    });
    document.getElementById("downBtn").addEventListener('click', function () {
      next(false);
    });

    card = 7;
    streak = 0;
    __size("cardTx", "fontSize", 72);
  </script>
</body>
</html>
