    }

    left = 359 - dayOfYear();
    if (left > 0) {
      document.getElementById("d").textContent = 'D-' + String(left);
    } else if (left == 0) {
      document.getElementById("d").textContent = '오늘이 크리스마스! 🎄';
    } else {
      document.getElementById("d").textContent = 'D+' + String(0 - left);
    }
    document.getElementById("today").textContent = '오늘: ' + String(new Date().toLocaleDateString());
  </script>
</body>
</html>
