  <h1 id="title">낚시 게임</h1>
  <h2 id="sea">🌊</h2>
  <button id="castBtn">낚싯대 던지기 🎣</button>
  <button id="reelBtn">당기기!</button>
  <h2 id="result"></h2>
  <script>
    var bite, fish;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("castBtn").addEventListener('click', function () {
      bite = false;
      document.getElementById("sea").textContent = '기다리는 중...';
      document.getElementById("result").textContent = '';
      setTimeout(function () {
        bite = true;
        document.getElementById("sea").textContent = '입질이다!! 당겨!';
        setTimeout(function () {
          if (bite) {
            bite = false;
            document.getElementById("sea").textContent = '🌊';
            document.getElementById("result").textContent = '놓쳤다... 🌊';
          }
        }, (1) * 1000);
      }, (mathRandomInt(2, 5)) * 1000);
    });
    document.getElementById("reelBtn").addEventListener('click', function () {
      if (bite) {
        bite = false;
        fish = (typeof fish === 'number' ? fish : 0) + 1;
        document.getElementById("sea").textContent = '🌊';
        document.getElementById("result").textContent = ['물고기를 잡았다! 🐟 ',fish,'마리'].join('');
      }
    });

    bite = false;
    fish = 0;
  </script>
</body>
</html>
