  <p id="avg">Average: -</p>
  <p id="top">Top: -</p>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var scores, best, sum, bestName, s;

    document.getElementById("addBtn").addEventListener('click', function () {
      if (!!document.getElementById("nm").value.trim().length && !!document.getElementById("sc").value.length) {
        scores.push((parseFloat(document.getElementById("sc").value) || 0));
        __add("rows", [document.getElementById("nm").value.trim(),': ',(parseFloat(document.getElementById("sc").value) || 0),''].join(''));
        if ((parseFloat(document.getElementById("sc").value) || 0) > best) {
          best = (parseFloat(document.getElementById("sc").value) || 0);
          bestName = document.getElementById("nm").value.trim();
        }
        sum = 0;
        for (var s_index in scores) {
          s = scores[s_index];
          sum = (typeof sum === 'number' ? sum : 0) + s;
        }
        document.getElementById("avg").textContent = 'Average: ' + String(Math.round((sum / scores.length) * 10) / 10);
        document.getElementById("top").textContent = ['Top: ',bestName,' (',best,')'].join('');
        document.getElementById("nm").value = '';
        document.getElementById("sc").value = '';
      }
    });

    scores = [];
    best = -1;
  </script>
</body>
