      x = Math.min(Math.max(x, 20), 280);
      __clear("cv");
      __circle("cv", x, 75, 20, col);
    }

    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowLeft") {
        e.preventDefault();
        x = (typeof x === 'number' ? x : 0) + -10;
        draw();
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowRight") {
        e.preventDefault();
        x = (typeof x === 'number' ? x : 0) + 10;
        draw();
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === " ") {
        e.preventDefault();
        col = 'hsl(' + Math.floor(Math.random() * 360) + ', 80%, 60%)';
