        document.getElementById("msg").textContent = '오답';
        __beep(261.63, 0.2);
      }
      document.getElementById("sc").textContent = '점수: ' + String(score);
      i = (typeof i === 'number' ? i : 0) + 1;
      next();
    }

    document.getElementById("o").addEventListener('click', function () {
      check(1);
    });
    document.getElementById("x").addEventListener('click', function () {
      check(0);
    });

    i = 1;
    score = 0;
