      document.getElementById("word").textContent = w;
      __show("word", "show");
      document.getElementById("res").textContent = '';
      setTimeout(function () {
        __show("word", "hide");
      }, (2) * 1000);
    });
    document.getElementById("chk").addEventListener('click', function () {
