<body>
  <h1 id="title">Guess my number (1-50)</h1>
  <input id="g" type="number" placeholder="Your guess">
  <button id="go">Guess</button>
  <h2 id="hint"></h2>
  <script>
    var secret;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("go").addEventListener('click', function () {
      if ((parseFloat(document.getElementById("g").value) || 0) < secret) {
        document.getElementById("hint").textContent = 'Too low';
      } else if ((parseFloat(document.getElementById("g").value) || 0) > secret) {
        document.getElementById("hint").textContent = 'Too high';
      } else {
        document.getElementById("hint").textContent = 'You got it!';
      }
    });

    secret = mathRandomInt(1, 50);
  </script>
</body>
</html>

