  <button id="flip">投げる</button>
  <p id="stats">表: 0 / 裏: 0</p>
  <script>
    var h, tl;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("flip").addEventListener('click', function () {
      if (mathRandomInt(1, 2) == 1) {
        h = (typeof h === 'number' ? h : 0) + 1;
        document.getElementById("face").textContent = '表';
      } else {
        tl = (typeof tl === 'number' ? tl : 0) + 1;
        document.getElementById("face").textContent = '裏';
      }
      document.getElementById("stats").textContent = ['表: ',h,' / 裏: ',tl].join('');
    });

    h = 0;
    tl = 0;
  </script>
