    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #ffffff; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
    input { font: inherit; padding: 9px 12px; margin: 4px; border: 1px solid #9ca3af; border-radius: 9px; }
  </style>
</head>
<body>
  <h1 id="title">Number Checker</h1>
  <input id="n" type="number" placeholder="Type a number">
  <button id="check">Check</button>
  <h2 id="eo"></h2>
  <h2 id="pr"></h2>
  <script>
    function mathIsPrime(n) {
      // https://en.wikipedia.org/wiki/Primality_test#Naive_methods
      if (n == 2 || n == 3) {
        return true;
      }
      // False if n is NaN, negative, is 1, or not whole.
      // And false if n is divisible by 2 or 3.
      if (isNaN(n) || n <= 1 || n % 1 !== 0 || n % 2 === 0 || n % 3 === 0) {
        return false;
      }
      // Check all the numbers of form 6k +/- 1, up to sqrt(n).
      for (var x = 6; x <= Math.sqrt(n) + 1; x += 6) {
        if (n % (x - 1) === 0 || n % (x + 1) === 0) {
          return false;
        }
      }
      return true;
    }

    document.getElementById("check").addEventListener('click', function () {
      document.getElementById("eo").textContent = (parseFloat(document.getElementById("n").value) || 0) % 2 === 0 ? String((parseFloat(document.getElementById("n").value) || 0)) + ' is even' : String((parseFloat(document.getElementById("n").value) || 0)) + ' is odd';
      document.getElementById("pr").textContent = mathIsPrime((parseFloat(document.getElementById("n").value) || 0)) ? 'It is a prime number ✔' : 'It is not prime';
    });
  </script>
</body>
</html>
