      __clear("game");
      __rect("game", px, 270, 30, 20, "#3b82f6");
      __rect("game", ex, ey, 30, 30, "#ef4444");
      ey = (typeof ey === 'number' ? ey : 0) + sp;
      if (ey > 240) {
        if (Math.abs(ex - px) < 30) {
          __timers.forEach(clearInterval);
          alert('Game over! Reload to play again');
        } else {
