          ex = mathRandomInt(0, 270);
          pts = (typeof pts === 'number' ? pts : 0) + 1;
          document.getElementById("score").textContent = pts;
          sp = (typeof sp === 'number' ? sp : 0) + 0.5;
        }
      }
    }, 30));

    px = 135;
    ex = 40;
    ey = 0;
    pts = 0;
    sp = 4;
  </script>
</body>
