      document.getElementById("joy").textContent = '기분: ' + String(fun);
      document.getElementById("energy").textContent = '에너지: ' + String(en);
      document.getElementById("face").textContent = food < 30 || fun < 30 ? '😟' : '😄';
    }

    document.getElementById("feed").addEventListener('click', function () {
      if (alive) {
        food = Math.min(Math.max(food + 15, 0), 100);
        showPet();
      }
    });
    document.getElementById("play").addEventListener('click', function () {
      if (alive) {
        fun = Math.min(Math.max(fun + 15, 0), 100);
        en = (typeof en === 'number' ? en : 0) + -10;
        showPet();
      }
    });
    __timers.push(setInterval(function () {
      if (alive) {
        food = (typeof food === 'number' ? food : 0) + -4;
        fun = (typeof fun === 'number' ? fun : 0) + -3;
        en = (typeof en === 'number' ? en : 0) + -2;
        showPet();
        if (food <= 0 || fun <= 0) {
          alive = false;
          document.getElementById("face").textContent = '👻';
          document.getElementById("msg").textContent = '😢 펫이 떠났어요... 새로고침해서 다시 키워요';
        }
      }
    }, 3000));
    document.getElementById("sleepBtn").addEventListener('click', function () {
      if (alive) {
        en = 100;
        document.getElementById("msg").textContent = '💤';
        setTimeout(function () {
          document.getElementById("msg").textContent = '';
        }, (2) * 1000);
      }
    });

    food = 70;
    fun = 70;
    en = 70;
    alive = true;
    showPet();
  </script>
