  <h2 id="title">숫자 맞추기 (1~50)</h2>
  <input id="guess" type="number" placeholder="숫자를 입력하세요">
  <button id="ok">확인</button>
  <p id="msg"></p>
  <p id="info">남은 기회: 5</p>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }

    var secret, left;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("ok").addEventListener('click', function () {
      left = (typeof left === 'number' ? left : 0) + -1;
      if ((parseFloat(document.getElementById("guess").value) || 0) == secret) {
        document.getElementById("msg").textContent = '정답이에요! 🎉';
        __show("ok", "hide");
      } else if ((parseFloat(document.getElementById("guess").value) || 0) < secret) {
        document.getElementById("msg").textContent = 'UP! 더 큰 수예요';
      } else {
        document.getElementById("msg").textContent = 'DOWN! 더 작은 수예요';
      }
      document.getElementById("info").textContent = '남은 기회: ' + String(left);
      if (left == 0 && (parseFloat(document.getElementById("guess").value) || 0) != secret) {
        document.getElementById("msg").textContent = '기회 끝! 정답은 ' + String(secret);
        __show("ok", "hide");
      }
    });

    secret = mathRandomInt(1, 50);
    left = 5;
  </script>
</body>
</html>
