      var x = Math.floor(Math.random() * text.length);
      return text[x];
    }

    document.getElementById("go").addEventListener('click', function () {
      n = (parseFloat(document.getElementById("len").value) || 0);
      if (n < 4 || n > 20) {
        document.getElementById("pw").textContent = '';
        document.getElementById("strength").textContent = 'Use a length from 4 to 20';
      } else {
        p = '';
        for (var count = 0; count < n; count++) {
          p = String(p) + String(textRandomLetter('abcdefghijkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789'));
        }
        document.getElementById("pw").textContent = p;
        document.getElementById("strength").textContent = 'Strength: ' + String(n < 8 ? 'Weak' : (n < 12 ? 'OK' : 'Strong'));
      }
    });
