      let text = '저체중';
      if (bmi >= 18.5) text = '정상';
      if (bmi >= 23) text = '과체중';
      if (bmi >= 25) text = '비만';
      document.getElementById('result').textContent = 'BMI ' + bmi.toFixed(1) + ' (' + text + ')';
    });
