      tries = (typeof tries === 'number' ? tries : 0) + 1;
      if ((parseFloat(document.getElementById("guessIn").value) || 0) == answer) {
        document.getElementById("result").textContent = 'Correct! Tries: ' + String(tries);
      } else if ((parseFloat(document.getElementById("guessIn").value) || 0) < answer) {
        document.getElementById("result").textContent = 'Higher ⬆';
      } else {
        document.getElementById("result").textContent = 'Lower ⬇';
      }
