    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
    input { font: inherit; padding: 9px 12px; margin: 4px; border: 1px solid #9ca3af; border-radius: 9px; }
    .box { display: flex; flex-direction: column; gap: 8px; padding: 12px; margin: 8px 0; border-radius: 12px; align-items: center; }
    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h1 id="title1">Case converter</h1>
  <input id="textBox" type="text" placeholder="Type something">
  <div id="btns" class="box row">
    <button id="upBtn">UPPERCASE</button>
    <button id="lowBtn">lowercase</button>
    <button id="countBtn">Count letters</button>
  </div>
  <h2 id="out"></h2>
  <script>
    var t, letters, i;

    document.getElementById("upBtn").addEventListener('click', function () {
      document.getElementById("out").textContent = document.getElementById("textBox").value.toUpperCase();
    });
    document.getElementById("lowBtn").addEventListener('click', function () {
      document.getElementById("out").textContent = document.getElementById("textBox").value.toLowerCase();
    });
    document.getElementById("countBtn").addEventListener('click', function () {
      t = document.getElementById("textBox").value;
      letters = 0;
      var i_end = t.length;
      var i_inc = 1;
      if (1 > i_end) {
        i_inc = -i_inc;
      }
      for (i = 1; i_inc >= 0 ? i <= i_end : i >= i_end; i += i_inc) {
        if (t.charAt((i - 1)) != ' ') {
          letters = (typeof letters === 'number' ? letters : 0) + 1;
        }
      }
      document.getElementById("out").textContent = String(letters) + ' letters (spaces not counted)';
    });
  </script>
</body>
</html>
