  <input id="bpm" type="number" placeholder="BPM (40~200)">
  <div id="btns" class="box row">
    <button id="go">시작</button>
    <button id="stop">멈춤</button>
  </div>
  <h1 id="beat">박자: 0</h1>
  <script>
    var __timers = [];
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var on, gap, acc, n;

    document.getElementById("go").addEventListener('click', function () {
      gap = 60 / Math.min(Math.max((parseFloat(document.getElementById("bpm").value) || 0), 40), 200);
      on = true;
      acc = 0;
    });
    document.getElementById("stop").addEventListener('click', function () {
      on = false;
    });
    __timers.push(setInterval(function () {
      if (on) {
        acc = (typeof acc === 'number' ? acc : 0) + 0.02;
        if (acc >= gap) {
          acc = 0;
          n = (typeof n === 'number' ? n : 0) + 1;
          document.getElementById("beat").textContent = '박자: ' + String(n);
          if (n % 4 == 1) {
            __beep(523.25, 0.05);
          } else {
            __beep(392.00, 0.05);
          }
        }
      }
    }, 20));

    on = false;
    acc = 0;
    n = 0;
  </script>
