      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var tasks, x;

    // 이 함수를 설명하세요...
    function draw() {
      document.getElementById("view").textContent = '';
      for (var x_index in tasks) {
        x = tasks[x_index];
        __add("view", x);
      }
      document.getElementById("cnt").textContent = ['남은 할 일: ',tasks.length,'개'].join('');
    }

    document.getElementById("add").addEventListener('click', function () {
      if (!!document.getElementById("task").value.trim().length) {
        tasks.push(document.getElementById("task").value);
        document.getElementById("task").value = '';
        draw();
      }
    });
    document.getElementById("undo").addEventListener('click', function () {
      if (tasks.length > 0) {
        tasks.pop();
        draw();
      }
    });

