      o.start(t); o.stop(t + sec);
    }

    var s, left, running, working, done;

    // 이 함수를 설명하세요...
    function showTime() {
      s = left % 60;
      document.getElementById("clock").textContent = [Math.floor(left / 60),s < 10 ? ':0' : ':',s].join('');
    }

    document.getElementById("go").addEventListener('click', function () {
      running = true;
    });
    document.getElementById("pause").addEventListener('click', function () {
      running = false;
    });
    __timers.push(setInterval(function () {
      if (running) {
        left = (typeof left === 'number' ? left : 0) + -1;
        showTime();
        if (left <= 0) {
          __beep(523.25, 0.6);
          if (working) {
            done = (typeof done === 'number' ? done : 0) + 1;
            document.getElementById("count").textContent = '완료한 뽀모도로: ' + String(done);
            working = false;
            left = 300;
            document.getElementById("mode").textContent = '☕ 쉬는 시간';
          } else {
            working = true;
            left = 1500;
            document.getElementById("mode").textContent = '🍅 집중 시간';
          }
          showTime();
        }
      }
    }, 1000));

    left = 1500;
    working = true;
    running = false;
    done = 0;
  </script>
