<body>
  <h1 id="title">🎂 Geburtstagsliste</h1>
  <input id="name" type="text" placeholder="Name">
  <input id="datum" type="text" placeholder="Datum (z.B. 3. Mai)">
  <button id="save">Speichern</button>
  <ul id="liste"></ul>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    document.getElementById("save").addEventListener('click', function () {
      if (!!document.getElementById("name").value.length && !!document.getElementById("datum").value.length) {
        __add("liste", [document.getElementById("name").value,' – ',document.getElementById("datum").value].join(''));
        document.getElementById("name").value = '';
        document.getElementById("datum").value = '';
      }
    });
  </script>
</body>
</html>
