    document.getElementById("outBtn").addEventListener('click', function () {
      if (bal - (parseFloat(document.getElementById("moneyBox").value) || 0) < 0) {
        alert('잔액 부족!');
      } else {
        bal = (typeof bal === 'number' ? bal : 0) + -(parseFloat(document.getElementById("moneyBox").value) || 0);
