      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }

    var qs, right, ans, i, score;

    document.getElementById("checkBtn").addEventListener('click', function () {
      right = document.getElementById("ansIn").value.trim() == ans[(i - 1)];
      document.getElementById("result").textContent = right ? '정답! 🎉' : '땡! ❌';
      if (right) {
        score = (typeof score === 'number' ? score : 0) + 1;
      }
      i = (typeof i === 'number' ? i : 0) + 1;
      document.getElementById("ansIn").value = '';
      document.getElementById("qTx").textContent = qs[(i - 1)];
      if (i > 3) {
        __show("row", "hide");
        document.getElementById("qTx").textContent = ['퀴즈 끝! 점수: ',score,' / 3'].join('');
      }
