<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>サイコロ</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #e0f2fe; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
  </style>
</head>
<body>
  <h1 id="diceTitle">サイコロ</h1>
  <h1 id="faceTx">🎲</h1>
  <button id="rollBtn">振る！</button>
  <p id="infoTx"></p>
  <script>
    var faces, roll;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("rollBtn").addEventListener('click', function () {
      roll = mathRandomInt(1, 6);
      document.getElementById("faceTx").textContent = faces[(roll - 1)];
      document.getElementById("infoTx").textContent = '出た目：' + String(roll);
