<head>
  <meta charset="UTF-8">
  <title>Lancer le dé</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #fce7f3; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
    .box { display: flex; flex-direction: column; gap: 8px; padding: 12px; margin: 8px 0; border-radius: 12px; align-items: center; }
    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h1 id="diceTitle">Lancer le dé</h1>
  <div id="faceRow" class="box row">
    <h1 id="faceTx">🎲</h1>
    <h1 id="faceTx2">🎲</h1>
  </div>
  <button id="rollBtn">Lancer !</button>
  <p id="infoTx"></p>
  <script>
    var faces, roll, roll2;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("rollBtn").addEventListener('click', function () {
      roll = mathRandomInt(1, 6);
      document.getElementById("faceTx").textContent = faces[(roll - 1)];
      roll2 = mathRandomInt(1, 6);
      document.getElementById("faceTx2").textContent = faces[(roll2 - 1)];
      document.getElementById("infoTx").textContent = 'Total : ' + String(roll + roll2);
    });

    faces = ['⚀', '⚁', '⚂', '⚃', '⚄', '⚅'];
  </script>
</body>
</html>
